/* Opossum Foot Canada — canada_only requirement data (2026-11-17 research passes).
   Generated from canada-data-pack.json by tools/build-canada-data.js — do not hand-edit.
   Loaded via <script> so the app works from file:// with no fetch/CORS issues.
   Fields are null/absent where the research does not cover the jurisdiction;
   the app renders only what exists and never invents rule text. */
window.OPOSSUM_FOOT_CANADA_DATA = {};
window.OPOSSUM_FOOT_CANADA_DATA["AB"] = {"check_interval":{"live_holding":"Non-killing devices: 48 hours under a Registered Fur Management Licence; 24 hours under a Resident Fur Management Licence.","killing":"No legal check requirement for killing devices.","note":null},"tenure":"Registered Fur Management Areas (~1,632 RFMAs; Senior Holder on a 5-year term, licence renewed annually by Sept 30) plus a separate Resident Fur Management Licence for private land and some non-RFMA public land.","trap_id_requirement":"None found - no trap owner-ID marking requirement in the sources searched (follow-up pass, Nov 17); identification runs through licence/tenure and pelt seals instead. Near-miss: black bear bait stations need a sign showing the owner's name or RFMA number - a bait-site sign, not a trap mark.","royalty":"None found in the current Wildlife Act, Wildlife Regulation AR 143/97, or the 2025-26 Guide to Trapping Regulations. [R2 Item 5]","nuisance_route":"Paid route exists - Damage Control Licence (Fish and Wildlife Stewardship): lethal control of specified wildlife causing/likely to cause damage or safety threats, typically valid ~1 month; never issued for capture/relocation, general nuisance, or population control. Counties hold DCLs and appoint contract trappers as external designates for problem beaver; some counties employ Problem Wildlife Specialists. [R1 s.4]","harvest_reporting_and_sealing":"Mandatory registration at a Fish & Wildlife office for fisher, lynx, otter, wolverine and all bobcat (wolverine skull must be delivered with the pelt). Fur Harvest Reports are required for annual licence renewal; Senior RFMA holders are additionally requested (voluntary) to submit logbooks to the Alberta Furbearer Harvest Program. [R1 s.5]","aihts_canada_only":{"canada_wide":"AIHTS in force in Canada since 1 June 1999 (Canada, the EU and Russia are parties; the US is not a party). FIC-certified traps mandatory per Phase 1 lists - killing traps: beaver, Canada lynx & bobcat, fisher, marten, muskrat (on land and underwater), otter, raccoon, weasels/ermine; restraining traps: beaver (cage), bobcat, Canada lynx, raccoon, wolf. Conventional steel-jawed leghold restraining traps on land are effectively banned for AIHTS species. Killing neck snares are NOT AIHTS traps and are not FIC-certified; provinces regulate snares separately. [R1 s.2a]","jurisdiction_specific":"Certified cage/box traps for raccoon mandatory from 2026-27; certified coyote restraining traps mandatory from 2028-29. Alberta guide: jaw-type leg/foothold restraining traps on land prohibited for badger, beaver, ermine, fisher, marten, muskrat and otter; conventional steel-jawed legholds on land prohibited for bobcat, coyote, lynx, raccoon and wolf - only certified/modified restraining traps for that group. [R1 s.2a]"},"aihts":{"alberta_implementation_url":"https://albertaregulations.ca/trappingregs/gen-regs.html","certified_killing_traps_phase_1":[{"models_approx":26,"note":"Phase 1 certified killing traps are mandatory for this species.","species":"Beaver"},{"models_approx":22,"note":"The Guide publishes one joint certified killing-trap list for Canada lynx and bobcat.","species":"Bobcat"},{"models_approx":22,"note":"The Guide publishes one joint certified killing-trap list for Canada lynx and bobcat.","species":"Canada lynx"},{"models_approx":18,"note":"Phase 1 certified killing traps are mandatory for this species.","species":"Fisher"},{"models_approx":19,"note":"Phase 1 certified killing traps are mandatory for this species.","species":"Marten"},{"models_approx":32,"note":"Certified killing traps for muskrat set on land.","species":"Muskrat (on land)"},{"models_approx":null,"note":"For muskrat underwater, any jaw-type trap (body-gripping or leghold) set as a submersion set is certified; no model list applies.","species":"Muskrat (underwater)"},{"models_approx":20,"note":"Phase 1 certified killing traps are mandatory for this species.","species":"Otter"},{"models_approx":35,"note":"Phase 1 certified killing traps are mandatory for this species.","species":"Raccoon"},{"models_approx":26,"note":"One joint list covers all weasel species.","species":"Weasel"}],"certified_restraining_traps_phase_1":[{"models_approx":6,"note":"Cage traps (Breathe Easy, Comstock, Dam, Ezee Set, Hancock, Koro Klam).","species":"Beaver"},{"models_approx":6,"note":"Certified restraining traps are mandatory for bobcat.","species":"Bobcat"},{"models_approx":4,"note":"Certified restraining traps are mandatory for Canada lynx.","species":"Canada lynx"},{"models_approx":5,"note":"Bridger T3, Duffer, Duke DP Coon Trap, Egg Trap, Lil' Grizz Get'rz.","species":"Raccoon"},{"models_approx":14,"note":"Certified restraining traps are mandatory for wolf.","species":"Wolf"}],"models_note":"Model counts were counted from the certified-trap lists printed in the Alberta Guide to Trapping Regulations 2026-2027 (General Regulations — Certified Traps), which republishes the Fur Institute of Canada AIHTS implementation list. This pass captured list structure and counts, not the full model-by-model list; full transcription is a follow-on task, as with Ontario.","models_transcribed":false,"no_certified_trap_required":["American mink","Red fox","Badger","Red squirrel","Striped skunk","Coyote (until the 2028/29 season, when certified foothold restraining traps become mandatory)"],"note":"Alberta implements the AIHTS in law: Wildlife Regulation (AR 143/1997) s. 107.1 incorporates Phase 1 of the competent authority's 'Certified Traps – AIHTS Implementation' document — the Fur Institute of Canada certified-trap list — by reference into the Regulation, and provides that a person shall not use any trap for a certified species unless the trap is currently listed by name and certified for that species. The Minister delegates amendment of the list to the competent authority and must publish the implementation list annually in the Alberta Guide to Trapping Regulations. 'Alberta has agreed to implement the AIHTS standards' (Guide, General Regulations).","phase_2_certified_not_yet_mandatory":[{"models_approx":25,"note":"Phase 2 certified foothold restraining traps for coyote; they become mandatory beginning with the 2028/29 trapping season (Guide, Important Changes).","species":"Coyote"},{"models_approx":23,"note":"Phase 2 certified cage and box traps for raccoon (Havahart, Ramconct, Tomahawk models). Although listed as Phase 2 in the Guide's trap lists, the Guide's Important Changes state they are mandatory beginning with the 2026/27 season — treat as mandatory for 2026-27.","species":"Raccoon (cage and box traps)"}],"source_updated":"2026-07-22","source_url":"https://fur.ca/wp-content/uploads/2026/07/CertifiedTrapsList_FIC_July-22-2026-_EN.pdf","trap_rules":["Only traps currently listed by name as certified for a species may be used for that species (Wildlife Regulation, s. 107.1(2)); it is unlawful to use traps that do not meet the AIHTS standards for a certified species (Guide, General Regulations).","Traps set for fur-bearing animals must be killing devices, leg snares, or live-container (cage/box) traps (Wildlife Regulation, s. 107(1)).","Leg-hold traps may be used only as killing devices, except for wolf, coyote, lynx, bobcat and raccoon, where they may also be used as restraining devices if the jaws are laminated (two steel parallel jaws, each at least 9 mm thick), offset, or padded (Wildlife Regulation, s. 107(3)). The 2026-27 Guide's summary of this rule says 8 mm; the Regulation says 9 mm and governs (see verification.known_gaps). Section 107 does not apply to fox (s. 107(4)).","Foothold traps with toothed jaws, or with an inside jaw spread of 23 cm (9 in.) or more, may not be used to trap furbearing animals (Guide, General Regulations).","A foothold trap that is not set as a killing device may not be set in a tree or on a pole (Wildlife Regulation, s. 108), and foothold traps not set as killing devices may be used only for bobcat, coyote, fox, lynx or wolf; every other furbearer must be taken in a killing device or a live-container trap (Guide, General Regulations).","Neck snares must have a locking device that prevents the snare from loosening once an animal is caught, except snares set underwater and single-strand wire snares for squirrel, rabbit or hare (Wildlife Regulation, s. 109).","New for 2026-27: a trapper who sets a baited killing neck snare within 200 m of the boundary of land occupied as a dwelling must notify the occupant (Wildlife Regulation, s. 109.1, added by AR 187/2026); the requirement does not apply where the adjacent land is larger than a quarter section.","Trap check: every non-killing trap must be examined at least once every 24 hours when set under a Resident Fur Management Licence, and at least once every 48 hours in any other case (i.e. under a Registered Fur Management Licence) (Wildlife Regulation, s. 110).","Snares may be used only under a Registered Fur Management Licence, or under a Resident Fur Management Licence for bobcat, coyote, fox, squirrel and wolf, and for beaver where the snare loop is completely underwater; a resident may also snare rabbit and hare with single-strand wire of 20 gauge or heavier and a loop diameter of 13 cm (5 in.) or less (Guide, General Regulations).","Seasonal snaring restriction: from October 1 to November 30, snaring of coyote, fox and wolf is prohibited in Fur Management Zones 4, 5 and 6 except in WMUs 314, 316, 318, 320, 322, 324, 330, 332, 334, 336, 337, 338, 348, 360, 410, 412, 414, 416, 417, 418, 507, 508 and 521 (Wildlife Regulation, Schedule 15, s. 9(1)(f)).","Slide-wire (drowning) sets must have a lock, must be anchored securely, and must be set in water deep enough to completely submerge the largest animal that may enter the trap (Guide, General Regulations).","Certified cage and box traps are mandatory for raccoon beginning with the 2026/27 season; certified foothold restraining traps for coyote become mandatory beginning with the 2028/29 season (Guide, Important Changes for 2026-27).","Trapping is prohibited in ecological reserves and, with limited RFMA exceptions, in wildlife sanctuaries; no furbearer may be harvested within 100 m of Highway 1A in WMU 410 except with traps. No person may remove, spring or otherwise interfere with another person's traps, except that a Registered FML holder may remove unlawful traps within their own RFMA and must report it immediately. Poison (except as authorized under the Agricultural Pests Act) and sharp hooks may not be used (Guide, General Regulations; Wildlife Regulation)."]},"license_summary":{"certified_traps":"Alberta has adopted the AIHTS certified-trap list in law: Wildlife Regulation s. 107.1 incorporates Phase 1 of the Fur Institute of Canada's 'Certified Traps – AIHTS Implementation' list by reference, and a person shall not use any trap for a certified species unless it is currently listed by name and certified for that species. The list is published annually in the Guide to Trapping Regulations. New for 2026/27: certified cage and box traps are mandatory for raccoon; certified foothold restraining traps for coyote become mandatory in 2028/29.","course":"First-time trappers — anyone who has never held a trapping licence in Alberta or elsewhere, or who has not completed a fur management course — must successfully complete the Alberta Trapper Education Course and pass a test on humane trapping and fur management before being licensed. Course information: Alberta Trappers' Association, Box 6020, Westlock, AB T7P 2P7, phone 780-349-6626, albertatrappers.com/trapper-courses.html.","fees":"Resident Fur Management Licence $20; Registered Fur Management Licence, senior holder, $40 plus an area fee of $10 for each 36 sq mi of RFMA area in excess of 72 sq mi, plus $10 for any remaining area, to a maximum area fee of $40 (the Guide presents the same fee as $10/$20/$30/$40 for RFMAs of 3/4/5/6 townships; the maximum combined licence and area fee is $80); Registered FML partner $20; Indian Fur Management Licence free; Métis Fur Management Licence — no fee stated in the Guide; Damage Control Licence — no fee stated. Fur dealer permits: Class 1 $100, Class 2 $500. Listed fees do not include GST. $5 from each Registered FML funds the Alberta Trappers' Compensation Program. (Guide, Licence Fees; cross-checked against Wildlife Regulation, Schedule 8, Part 3 — the two agree exactly.)","harvest_report":"Registered FML holders must submit the Registered Fur Harvest Report (Form WA12) with the annual licence renewal by September 30, covering the species and number of all furbearers harvested on their RFMA(s), including harvest by their spouse and resident children under 18. Resident FML holders are asked to complete the Resident Fur Harvest Report (Form WA12A), by WMU, on or before September 30. New for 2026-27: senior RFML holders are requested to submit completed trapping activity reports (logbooks) to the Alberta Furbearer Harvest and Trapping Effort Program (online at atalogbook.ab-conservation.com; a pull-out logbook is included in the centre of the printed Guide). Fur Harvest Reports remain required for annual renewal.","licence_types":"Registered Fur Management Licence (senior holder or partner) — for a Registered Fur Management Area; Resident Fur Management Licence — private lands the holder owns, leases or occupies, or other private land with Form WA 19A permission; Indian Fur Management Licence — First Nation individuals within their First Nation boundaries, issued by Band Administration Offices; Métis Fur Management Licence — Métis Settlement members within their settlement, issued by Métis Settlement Supervisors; Damage Control Licence — for problem wildlife not covered by the no-licence authorities.","licensing_transition":"Since July 2021, all fur management licences are issued through AlbertaRELM and require a WiN (Wildlife Identification Number) activation ($8 + GST). Vacant RFMAs are listed at, and applied for through, Fish and Wildlife District Offices.","non_licence_animals":"Raccoon and skunk are classed as non-licence animals: they may be hunted or trapped during all seasons by the owner or occupant of land, a person authorized by the owner or occupant, or the holder of a licence authorizing the trapping of furbearers (Wildlife Regulation, Schedule 1, s. 7(12)). The open season for hunting non-licence animals is January 1 to December 31, except in Big Game Zone 17, where there is no open season (Schedule 15, s. 12).","permission":"A Resident Fur Management Licence holder trapping on private land they do not own, lease or occupy must carry the licence together with Form WA 19A, the landowner's signed written authorization to hunt fur-bearing animals, and produce both on the request of a Fish and Wildlife Officer. Use of neck snares for wolf, coyote, fox and bobcat on another person's land requires the landowner's additional written authorization (Form WA 19A provides for it).","problem_wildlife":"Without a licence (Wildlife Regulation, Schedule 1, s. 7; Guide, Control of Problem Wildlife): beaver may be hunted and trapped year-round on private land by the owner or occupant or a resident with written permission; badger and red squirrel may be hunted or trapped year-round by a resident on private land with a right of access; muskrat may be hunted year-round on private land (owner/occupant, or resident with written authorization); red fox may be hunted (not trapped) year-round by a resident on private land with a right of access; coyote may be hunted (not trapped) year-round province-wide by residents with a right of access, landowners/occupants and livestock keepers (pelts must be salvaged when hunting under a livestock keeper's written authorization on Green Area lands); wolf may be hunted (not trapped) year-round on private land, and by livestock keepers on public land, extending to land within 8 km (5 mi) of that land; raccoon and skunk may be hunted or trapped year-round by landowners/occupants, their authorized persons, or licensed trappers; bobcat may be hunted (not trapped) by residents from November 1 to the last day of February in WMUs 102, 104, 106, 108, 112, 116, 118, 119 and part of WMU 110; rabbit and hare may be hunted year-round without a licence on land with a right of access, and snared by residents with single-strand wire snares. A Damage Control Licence may be necessary for other species destroying property.","quotas":"The Alberta season table (Guide p. 15; Wildlife Regulation, Schedule 15, Table 5) sets NO daily, possession or season bag limits for any furbearer. Instead, the Minister may set an open season quota — the maximum number of otter, wolverine, lynx and fisher that may be killed in a Registered Fur Management Area during the open season (Schedule 15, s. 8.7). A quota that is set must immediately be made publicly available on a department website, and when the quota is reached in an RFMA the open season no longer applies there (Schedule 15, s. 9(1)(b)). The 2026-27 Guide does not print quota numbers — guides up to at least 2018-19 printed an RFMA limits table (a basic limit per RFMA plus per-township increments for fisher, lynx, otter and wolverine), which is absent from the 2025-26 and 2026-27 Guides — and current quota values were not located in this pass; they are recorded as a known gap.","registration_tagging":"Mandatory registration: fisher, lynx, otter and wolverine killed in an open season must be registered within 30 days of the close of that season (killed outside an open season, within 30 days of the kill), and in all cases before sale, processing or export, by presenting the pelt at a Fish and Wildlife District Office or approved location. All bobcat taken under any authority must be registered before the skin is sold, processed or exported from Alberta, or within 30 days after harvest. Wolverine registration requires the skull with the pelt (tooth and DNA sample). Any cougar harvest, including an accidental capture, must be registered at a district office immediately. A provincial export permit is required to export any furbearer skin or pelt from Alberta (exceptions include beaver castor and oil glands, claws, skulls and teeth of furbearers, processed skins, and lawfully possessed coyote skins), and a CITES permit is required to export wolf, lynx, bobcat, otter or black bear across an international boundary. Raw skins may be sold only to a licensed fur dealer; dealers verify a partner's licence and WA188 card, record lynx, fisher, wolverine and otter on a Furbearers Registration Certificate (Form WA324), report monthly, and retain records for two years. Exception: non-residents within 30 miles of Fort Smith, NWT, trapping on an RFMA wholly north of the north boundary of Township 118 and east of Wood Buffalo National Park are exempt from mandatory registration of fisher, lynx, otter and wolverine and from the provincial export permit for those species.","report_violation":"Report A Poacher: 1-800-642-3800 (24 hours a day, 7 days a week), or online at alberta.ca/report-poacher. Report violations on public land or in provincial parks to 310-LAND; emergencies 9-1-1.","resident_licence":"An Alberta resident aged 14 or older may obtain a Resident Fur Management Licence ($20) to hunt or trap furbearing animals on land they own, lease (other than a lease within an RFMA) or occupy, or on other private land with the owner/occupant's written permission on Form WA 19A, which must be carried with the licence. Resident FML holders may NOT take fisher, otter, lynx or wolverine anywhere in Alberta, and may not take marten in Fur Management Zone 3.","rfma_system":"Alberta has approximately 1,630 Registered Fur Management Areas (the Guide's licensing page says approximately 1,632; its 2025/26 statistics say 1,628) — parcels of public (Crown) land whose boundaries are described on the Registered Fur Management Licence. The senior holder is authorized for a five-year term and must renew the licence each year on or before September 30, submitting the Registered Fur Harvest Report (Form WA12); failure to renew may result in revocation of RFML privileges. The senior holder may add partners under a Fur Management Area Partnership Agreement approved in writing by a wildlife biologist; partnership agreements are confirmed annually, and partners are issued a licence and a wallet-size WA188 card valid July 1 to June 30. The senior holder's spouse, or a resident child under 18 of the senior holder, may hunt or trap on the RFMA without a licence, with the harvest included in the senior holder's WA12. A senior holder may transfer an RFMA by conditional relinquishment, in person at a government office. An RFML authorizes hunting and trapping only on the holder's RFMA(s) or on lands the holder owns, leases or occupies; a Resident Fur Management Licence is required for other private lands.","trap_check":"Every non-killing trap must be examined at least once every 24 hours when set under a Resident Fur Management Licence, and at least once every 48 hours in any other case (i.e. under a Registered Fur Management Licence) (Wildlife Regulation, s. 110).","trapping_licence":"A fur management licence is required to hunt or trap furbearing animals in Alberta under the Wildlife Act and the Wildlife Regulation (Alberta Regulation 143/1997), except under the no-licence problem-wildlife authorities and for non-licence animals (raccoon and skunk). A fur management licence or trapper's identification card must be carried at all times while trapping.","youth":"A resident under 18 whose parent holds a Registered Fur Management Licence (senior holder or partner) may hunt or trap in that RFMA subject to seasons, quotas and restrictions; residents aged 12 to 17 may trap under the senior holder's direct supervision with the senior holder's permission and written parent/guardian authorization. A resident under 16 whose parent holds a Resident Fur Management Licence may hunt or trap on the parent's lands (the WA 19A lands); residents aged 12 to 13 may hunt or trap under the licence holder's direct supervision with the holder's permission and written parent/guardian authorization."},"seasons_status":null,"seasons_note":null};
window.OPOSSUM_FOOT_CANADA_DATA["BC"] = {"check_interval":{"live_holding":"72 hours for holding/non-killing traps; 24 hours for egg traps (raccoon).","killing":"14 days for killing traps/killing snares on a trapline (B.C. Reg. 338/82 s. 3.05).","note":null},"tenure":"Registered traplines on Crown land (holder must actively trap to the regional manager's satisfaction or risk cancellation); private-land trapping needs the owner's written permission.","trap_id_requirement":"None found - no trap owner-ID marking requirement in the sources searched (follow-up pass, Nov 17); identification runs through licence/tenure and pelt seals instead. BC's Assigned Trapper Number is used on fur-sale/export/royalty paperwork, not on traps.","royalty":"3% of the 3-year average Canadian auction price per pelt, payable by a trapper who keeps a pelt (not payable if the pelt is sold to a licensed fur trader); due to the regional manager by March 31 following the year taken (B.C. Reg. 338/82 s. 3.09). [R1 s.5; R2 Item 5]","nuisance_route":"Paid route exists - General Wildlife Permit (Permit Regulation, B.C. Reg. 253/2000): s. 2(b) hunt/trap/kill on own property in/out of season; s. 2(c)(iii) hunt/trap/kill on others' property for problem wildlife (application via FrontCounter BC listing professional qualifications; records due within 21 days after permit expiry). Schedule C species need no permit with owner permission. [R1 s.4]","harvest_reporting_and_sealing":"Compulsory reporting within 15 days after season end for listed species, plus a general compulsory report of furbearers killed (Reg. 338/82 ss. 3.16, 3.16.1); compulsory inspection/carcass submission for wolverine, lynx, bobcat and wolf by region/MU and for fisher in any MU with an open season; fur traders must submit lynx pelt measurements. [R1 s.5]","aihts_canada_only":{"canada_wide":"AIHTS in force in Canada since 1 June 1999 (Canada, the EU and Russia are parties; the US is not a party). FIC-certified traps mandatory per Phase 1 lists - killing traps: beaver, Canada lynx & bobcat, fisher, marten, muskrat (on land and underwater), otter, raccoon, weasels/ermine; restraining traps: beaver (cage), bobcat, Canada lynx, raccoon, wolf. Conventional steel-jawed leghold restraining traps on land are effectively banned for AIHTS species. Killing neck snares are NOT AIHTS traps and are not FIC-certified; provinces regulate snares separately. [R1 s.2a]","jurisdiction_specific":null},"aihts":{"note":"British Columbia implements AIHTS through the Wildlife Act Commercial Activities Regulation, B.C. Reg. 338/82, s. 3.04 and Schedule 3.04, which lists the lawful traps by species and trap position; the Synopsis (pp. 74-75) reprints the certified-trap lists. A 'certified trap' is one listed in Schedule 3.04 for that species and position. The Fur Institute of Canada maintains the national certified-trap list (updated July 22, 2026); B.C.'s lists are drawn from it. AIHTS was agreed in 1997 and ratified by Canada in June 1999. Since the 2007-2008 season B.C. trappers have been required by law to use only AIHTS-certified traps for the mandated species; the requirement is phased in species by species once enough trap types are certified and trappers are notified.","source_url":"https://www2.gov.bc.ca/gov/content/sports-culture/recreation/fishing-hunting/hunting/trapping-in-bc/trapping-standards","fic_list_url":"https://fur.ca/wp-content/uploads/2026/07/CertifiedTrapsList_FIC_July-22-2026-_EN.pdf","source_updated":"2026-07-22","models_transcribed":false,"models_note":"This pass captured the mandate structure and species categories from the Synopsis (pp. 74-75) and the Trapping Standards page, not the full model-by-model lists. The pp. 74-75 tables could not be transcribed with dataset-grade reliability from the PDF text extraction (multi-column interleaving). Full transcription from the PDF (or from the FIC list) is a defined follow-on task. Certification is not the same as current manufacturing: several certified models are legacy/discontinued. Do not present the certified list as a shopping list without a retailer-availability check.","certified_killing_traps":[{"species":"Beaver","models_approx":null,"note":"Underwater or on land; list on Synopsis p. 74."},{"species":"Bobcat and Lynx","models_approx":null,"note":"Combined list on Synopsis p. 74."},{"species":"Fisher","models_approx":null,"note":""},{"species":"Marten","models_approx":null,"note":""},{"species":"Muskrat","models_approx":null,"note":"On land only; and underwater only: any jaw-type trap (body gripping or foot-hold) set as a submersion set that exerts clamping force and keeps the animal underwater."},{"species":"River otter","models_approx":null,"note":""},{"species":"Raccoon","models_approx":null,"note":""},{"species":"Weasel","models_approx":null,"note":"Covers least, long-tailed and short-tailed weasel."}],"certified_restraining_traps":[{"species":"Beaver","models_approx":null,"note":"Live cage traps (Breathe Easy, Comstock, Dam Beaver, Ezee Set, Hancock, Koro 'Klam')."},{"species":"Bobcat","models_approx":null,"note":""},{"species":"Lynx","models_approx":null,"note":""},{"species":"Wolf","models_approx":null,"note":"Foot snares and specified soft-catch / laminated / offset foot-hold models."}],"no_certified_trap_required":["Coyote","Red fox","Striped skunk","Squirrel","Wolverine","Black bear","Mink"],"trap_rules":["Only certified traps may be used for the mandated species/positions (Synopsis p. 72; B.C. Reg. 338/82 s. 3.04 and Schedule 3.04).","It is an offence to trap within 200 m of a dwelling unless using, on land, a live box trap or egg trap, or on/in water a Conibear not larger than size #330 or equivalent, foot-hold traps not larger than size #2, or submarine traps (Synopsis p. 71; B.C. Reg. 338/82 s. 3.06).","Trap check: holding/non-killing traps every 72 hours (24 hours on private property); egg traps every 24 hours; killing traps and killing snares every 14 days (B.C. Reg. 338/82 s. 3.05; Synopsis p. 71).","It is an offence to use a foot-hold trap with teeth or other projections on the jaws; to use a killing snare on land unless it has a locking device, is designed for squirrels/hares, or is a mechanically powered killing snare; to use snare wire heavier than 20 gauge or braided wire unless licensed/authorized to trap; to set spring poles or running poles unless equipped with a killing trap; to use a trap with a spearing device; to use a Conibear larger than (not including) #220 for land sets within any municipality (Synopsis p. 73).","Egg traps may only be used by a person holding a valid trapping licence, and the trap must be securely fastened or anchored so a caught animal cannot drag it away (Synopsis p. 73).","Fisher exclusion boxes are required for listed 120-size traps set on land in MUs 3-30, 3-31, 5-1, 5-2, 5-12, 5-13 and 5-14: box at least 17 inches long (outside), entry hole no more than 56 mm (2-1/4 in) in diameter, side slot at least 10 in long and no more than 1 in high (B.C. Reg. 338/82 s. 3.04.1; Synopsis p. 73).","Wolf foot-hold traps must be solidly fastened with no more than 60 cm of chain (Synopsis p. 75, footnote 1).","Muskrat submerging sets smaller than size #1 1/2 require a minimum 150 g weight securely attached (Synopsis p. 75, footnote 2).","In Region 5 it is an offence to set a killing snare to trap wolves or coyotes within 10 m of where bait is placed (Synopsis p. 73).","Killing snares in the Kootenay Region are limited to Dec 1 - Mar 31 for wolf (Provincial Trapping Seasons table footnote, p. 76).","It is an offence to trap wildlife using a firearm from one hour after sunset until one hour before sunrise the following day, unless using a firearm to kill a furbearing animal caught in a trap on a registered trapline (Synopsis p. 71).","A trapped furbearing animal found alive must be immediately released or killed; a trapping licence does not authorize possession of live wildlife, and live trapped furbearers must not be transported and released elsewhere without a permit (Synopsis pp. 71-72).","It is an offence to cause or allow dogs to pursue furbearers under the authority of a trapping licence; electronic or recorded calls may be used for trapping wolf, coyote, bobcat or lynx only (Synopsis p. 73).","Future restriction under consideration: restricting box/cage traps for live-trapping raccoons and restraining traps for live-trapping coyotes to AIHTS-certified traps only, starting in the 2028-2029 trapping year (Synopsis p. 72)."]},"license_summary":{"trapping_licence":"A trapping licence is required (Wildlife Act s. 11, s. 40.1). The regional manager may issue one to a person who is a Canadian citizen or a permanent resident of Canada. Licences are issued through FrontCounter BC (online application, Basic or Business BCeID). A FWID (Fish & Wildlife ID, obtained through BC Hunting Online) is required to submit trapping reports.","course":"It is an offence to trap unless you have completed a trapper education course approved by the Director of the Wildlife Branch (B.C. Reg. 338/82 s. 3.10). Approved courses: B.C. since July 1, 1982; Quebec since July 1, 1988; Yukon, Alberta and Ontario since July 1, 1989. The BC Trappers Association delivers the 3-day Trapper Education Program (250-962-5452, info@bctrappers.ca). First-time applicants attach a photocopy of the course certificate.","fees":"Trapping licence $40.00 for one year / $200.00 for five years (GST included where applicable; Habitat Conservation Trust Fund surcharge included - $32 fee + $8 surcharge for one year; $160 + $40 for five years, B.C. Reg. 338/82 Schedule 2.02). Duplicate licence $10.00. Registered trapline transfer fee $50.00. Fur trader's licence $100.00; fur trader trading from a place of business in another province $400.00. (Synopsis p. 73; B.C. Reg. 338/82 Schedule 2.02.)","licence_year":"Annual trapping licences are valid from the later of July 1 of the year of issue or the issue date, to the following June 30 (B.C. Reg. 338/82 s. 2.04). A five-year licence runs to June 30 of the year five years after the year of issue (s. 2.04.1). The trapping licence year 2026-27 runs July 1, 2026 to June 30, 2027.","quotas":"No bag limits are printed in the Provincial Trapping Seasons table, except the black bear quota of 2 in one licence year (B.C. Reg. 338/82 s. 3.20). Trapping is managed by registered traplines (Class 1 species: beaver, fox, marten, mink, muskrat, raccoon, skunk, squirrel, weasel) and regional regulation (Class 2: lynx, bobcat, wolverine, fisher, river otter; Class 3: wolf, coyote). Hunting bag limits for furbearers are in the regional General Open Seasons tables (see season rows).","traplines":"It is an offence to trap in any area unless you are the registered holder of the trapline for that area or are authorized by regulation or permit. Registration of a trapline on Crown land may only be granted to a person 19 years of age or older who is a Canadian citizen or permanent resident. No more than one trapline per person unless traplines are adjoining and a fur management plan is approved by the Regional Manager. Registration gives no proprietary rights in wildlife. A registered trapline must be actively trapped (or used by a licensed trapper, or temporarily discontinued with permission for up to two years); a trapline is unused if, within a year, the holder fails to take furbearers of $200 value or 50 pelts, unless that is unreasonable for the trapline. Transfer/relinquishment must be approved by the Regional Manager; transfer fee $50.00. Private-property trapping requires written permission of the owner/occupier. (Synopsis p. 72; B.C. Reg. 338/82 ss. 3.13-3.19.) Approximately 2,900 registered traplines in B.C. (BC Furbearer Management Guidelines).","trap_check":"A licence holder commits an offence by failing to examine: (a) every 72 hours, every holding or non-killing trap except an egg trap; (b) every 24 hours, every egg trap; (c) every 14 days, every killing trap or killing snare (B.C. Reg. 338/82 s. 3.05; Synopsis p. 71). On private property, holding/non-killing traps must be examined at least once every 24 hours. A trapped furbearing animal found alive must be immediately released or killed.","harvest_report":"Licensed trappers must submit a trapping harvest report each trapping licence year (July 1 to June 30), due 31 days after the end of the licence year - by July 31 (July 31, 2027 for 2026-27). A report is required even if no harvest occurred. Non-filing: the trapper cannot buy a licence, permit, limited entry hunting application or guide territory certificate until a report is submitted, and may be charged a $460 fine. Report online through WILD (BC Hunting Online) or on the form at any FrontCounter BC office. (Synopsis p. 72.)","compulsory_reporting":"Trappers must report within 15 days following the end of the trapping season: fisher in all MUs when trapped in an open season; wolverine in Regions 5, 6, 7A and 7B; bobcat in Region 2; wolf in Region 1 and MUs 2-5, 2-6, 2-11 to 2-16. (Synopsis p. 72.)","compulsory_inspection":"Furbearers trapped outside an open season (incidental) must be submitted (carcass and pelt) for Compulsory Inspection: fishers within 30 days of the kill; all others by June 30 of the licence year. These animals cannot be reclaimed. The pelt of a wolverine trapped in Region 3 during an open season must be submitted within 15 days after the last day of the continuous season (and before export if applicable). (Synopsis pp. 72-73.)","royalties":"Royalty must be paid to keep the pelt/skin of a furbearing animal lawfully taken under a trapping licence, unless sold to a licensed fur trader. Royalty is 3% of the average auction price for that species over the preceding three years. Current schedule (gov.bc.ca, as of January 14, 2026), per pelt: beaver $1.03, black bear $8.69, bobcat $11.29, coyote $0.68, fisher $1.94, fox $0.73, lynx $5.33, marten $2.08, mink $0.32, muskrat $0.07, otter $1.40, raccoon $0.21, skunk $1.38, squirrel $0.04, weasel (ermine) $0.25, wolf $9.62, wolverine $16.18. An Assigned Trapper Number (ATN) is required by the fur trader when accepting, exporting and selling fur, and when paying royalties. (Synopsis p. 73.)","export_cites":"Any raw fur or skin shipped out of the province for commercial purposes must be accompanied by an Export Permit (Synopsis p. 72). A CITES Export Permit is required to export out of Canada all bears, cougar, lynx, bobcat, wolf, sea otter, or river otter or parts of these animals (Synopsis p. 16).","certified_traps":"A person using killing traps for beaver, bobcat, fisher, lynx, marten, muskrat, river otter, raccoon or weasels, or restraining traps for beaver (cage traps), bobcat, lynx or wolf is required by law to use only species-specific traps included in B.C.'s trapping regulations that have been certified under the Agreement on International Humane Trapping Standards (Synopsis p. 72; B.C. Reg. 338/82 Schedule 3.04; certified-trap lists Synopsis pp. 74-75). See the 'aihts' section of this dataset.","hunting_furbearers":"Furbearers may also be hunted under a hunting licence in regional General Open Seasons (bobcat, lynx, coyote, wolf, wolverine, raccoon, skunk; see hunting season rows in this dataset for Regions 2, 5, 6, 7A, 7B and 8). Cougar and black bear are big game hunted under the Hunting Regulation (B.C. Reg. 190/84); their hunting seasons were not transcribed in this pass. Hunting rows for Regions 1, 3 and 4 were not verified in this pass (see known_gaps).","permission":"Trap only on your registered trapline, or on private property with the written permission of the property owner or occupier. Trapping in ecological reserves is prohibited; trapline tenure in provincial parks, conservancies and recreation areas is subject to the Park Act and requires a Park Use / Resource Use Permit.","report_violation":"Report All Poachers and Polluters (RAPP), 24-hour hotline 1-877-952-7277 (1-877-952-RAPP), or #7277 on a cellphone. Online: forms.gov.bc.ca/environment/rapp/. Reports go to the Conservation Officer Service."},"seasons_status":null,"seasons_note":null};
window.OPOSSUM_FOOT_CANADA_DATA["MB"] = {"check_interval":{"live_holding":"Live-holding devices: 72 hours; live traps for defence of property: 24 hours (secondary table).","killing":"No check requirement found.","note":null},"tenure":"Registered Trapline system - 46 community-based RTL sections in the north (lines cannot be sold, inherited or handed down; awarded by competition/scoring) plus Open Area Zones and Special Trapping Areas.","trap_id_requirement":"None found - no trap owner-ID marking requirement in the sources searched (follow-up pass, Nov 17); identification runs through licence/tenure and pelt seals instead.","royalty":"No royalty currently payable - Wildlife Act s. 41 machinery survives, but the current Wildlife Fees Regulation (M.R. 31/92) prescribes fees only; the royalty schedule was removed in the 2016 amendments. [R2 Item 5]","nuisance_route":"Paid trapping generally prohibited - Wildlife Act s. 18 bars hunting/trapping for hire, gain or remuneration except as permitted. Narrow routes: (i) Targeted Predator Removal Program - a producer with a MASC wildlife-damage claim contacts the Manitoba Trappers Association, which assigns a trapper; trappers are paid time, mileage and equipment plus a per-wolf incentive; lethal only. (ii) Conservation Officer special permits for out-of-season property-protection harvest. Landowner self-help under s. 46 (no licence) must be reported to a CO within 10 days. [R2 Item 3]","harvest_reporting_and_sealing":null,"aihts_canada_only":{"canada_wide":"AIHTS in force in Canada since 1 June 1999 (Canada, the EU and Russia are parties; the US is not a party). FIC-certified traps mandatory per Phase 1 lists - killing traps: beaver, Canada lynx & bobcat, fisher, marten, muskrat (on land and underwater), otter, raccoon, weasels/ermine; restraining traps: beaver (cage), bobcat, Canada lynx, raccoon, wolf. Conventional steel-jawed leghold restraining traps on land are effectively banned for AIHTS species. Killing neck snares are NOT AIHTS traps and are not FIC-certified; provinces regulate snares separately. [R1 s.2a]","jurisdiction_specific":null},"aihts":{"certified_killing_traps_schedule_1":[{"species":"Beaver","models_approx":32,"note":"Approved devices listed in M.R. 245/90 Schedule B (killing and restraining devices combined - the regulation does not split them)."},{"species":"Bobcat","models_approx":28,"note":"Approved devices listed in M.R. 245/90 Schedule B."},{"species":"Fisher","models_approx":15,"note":"Approved devices listed in M.R. 245/90 Schedule B."},{"species":"Lynx","models_approx":26,"note":"Approved devices listed in M.R. 245/90 Schedule B."},{"species":"Marten","models_approx":18,"note":"Approved devices listed in M.R. 245/90 Schedule B."},{"species":"Muskrat","models_approx":37,"note":"Approved devices listed in M.R. 245/90 Schedule B: 37 named models plus a generic underwater jaw-type trap entry."},{"species":"River otter","models_approx":18,"note":"Approved devices listed in M.R. 245/90 Schedule B."},{"species":"Raccoon","models_approx":30,"note":"Approved devices listed in M.R. 245/90 Schedule B: 30 named models plus a generic foot-encapsulating trap entry."},{"species":"Weasel","models_approx":26,"note":"Approved devices listed in M.R. 245/90 Schedule B."},{"species":"Wolf","models_approx":13,"note":"Approved devices listed in M.R. 245/90 Schedule B."}],"certified_restraining_traps_schedule_2":[{"species":"Beaver","models_approx":null,"note":"The guide's Phase 1 (mandatory) list includes certified restraining traps for beaver (cages). Model counts are in the Fur Institute of Canada list and were not transcribed; Manitoba's binding list is M.R. 245/90 Schedule B."},{"species":"Bobcat","models_approx":null,"note":"Phase 1 (mandatory) certified restraining traps per the guide; counts not transcribed."},{"species":"Lynx","models_approx":null,"note":"Phase 1 (mandatory) certified restraining traps per the guide; counts not transcribed."},{"species":"Wolf","models_approx":null,"note":"Phase 1 (mandatory) certified restraining traps per the guide; counts not transcribed."},{"species":"Coyote","models_approx":null,"note":"Phase 2 per the guide: certified restraining traps exist for coyote but are NOT yet mandatory in Manitoba; implementation year to be determined, with at least three years' notice promised."},{"species":"Badger","models_approx":0,"note":"Phase 2 per the guide: no killing trap is certified for badger to date."}],"models_note":"This pass captured schedule structure and model counts per species from M.R. 245/90 Schedule B (243 named models plus 2 generic entries across 10 species); individual model names were counted, not transcribed. The Fur Institute of Canada certified-trap list cross-referenced through the 2026-2027 Manitoba Trapping Guide (pp. 25-26) is the July 22, 2026 edition.","models_transcribed":false,"no_certified_trap_required":["Arctic fox","Badger","Black bear","Coyote","Mink","Red fox","Red squirrel","Wolverine"],"note":"Manitoba implements the Agreement on International Humane Trapping Standards through its own approved-device list, not by incorporating the Fur Institute of Canada list by reference: M.R. 245/90 s. 7(1)(e) restricts the ten Schedule B species to the devices listed in Schedule B (243 named models plus 2 generic entries; Schedule B last amended by M.R. 98/2026), and s. 7(1.1) allows any device for species not in Schedule B, subject to the general trap rules. The regulation never uses the word 'certified'; the 2026-2027 Trapping Guide (pp. 24-26) reproduces the FIC certified-trap lists in two phases - Phase 1 certified traps are mandatory (killing traps for beaver, fisher, marten, muskrat, river otter, raccoon, lynx and bobcat, weasel; restraining traps for beaver (cages), bobcat, lynx, wolf), while Phase 2 traps are certified but not yet mandatory (including coyote restraining traps; no killing trap is yet certified for badger), with the implementation year to be determined and at least three years' notice promised. Guide rule 29 matches the Schedule B species list. Three new certified traps were introduced for 2026-27 (guide, minister's message). The guide also carries a trap sales warning: vendors have sold non-certified traps as certified, and the onus is on the trapper. Approved power-assisted snares are listed separately in Schedule C (5 torsion springs, 4 breakaway devices, and a cam lock with teeth) for coyote and red fox.","manitoba_schedules_url":"https://web2.gov.mb.ca/laws/regs/current/245-90.php?lang=en","source_updated":"2026-07-22","source_url":"https://web2.gov.mb.ca/laws/regs/current/245-90.php?lang=en","trap_rules":["Seasons open at 12:00 a.m. on the opening date and close at 11:59 p.m. on the closing date (M.R. 245/90 s. 2). Sunday trapping is allowed (s. 5). The trapping year runs September 1 to August 31 (s. 13(4)). The minister may extend a Schedule A season by written notice (s. 3.1).","Trap check: live holding devices must be inspected at least once every 72 hours (s. 8(1)); live trapping in defence of property must be checked every 24 hours (s. 8(3)). A live-trapped animal must be humanely killed immediately (s. 8(2)). The guide's responsible-trapping advice (not law) is to inspect live-holding devices daily in the early morning.","Only approved devices listed in Schedule B may be used for beaver, bobcat, fisher, lynx, marten, muskrat, river otter, raccoon, weasel, and wolf (s. 7(1)(e)); any device may be used for a species not in Schedule B (s. 7(1.1)), subject to the general rules.","No toothed or serrated traps; no hooks; no spring-pole sets; no leghold trap set in a tree or on a pole; leghold jaw spread must not exceed 23 cm (s. 7(1)).","110-size body-gripping traps (8 named models in the regulation) must not be used on land for any animal other than muskrat (s. 7(1.2)).","Leghold traps for beaver, mink, and river otter may be used only in drowning sets (s. 7(3)); no leghold traps for badger, red squirrel, weasel, or wolverine (s. 7(4)); leghold traps for coyote, arctic fox, and red fox require pad inserts, laminated jaws, or offset jaws of at least 5 mm (s. 7(5)).","Black bear: firearm only; not in a den; not a female with cubs (s. 7(2)).","Submarine traps may be used only for muskrat or mink (s. 7.1).","Common snares may be used only in the registered trapline area or the Northern Special Trapping District; exceptions are under-ice beaver snares in the open trapping area, power snares anywhere, and approved power-assisted snares (Schedule C devices) for coyote or red fox anywhere (s. 9). A snare on land requires a mechanical locking device that prevents the noose from expanding (s. 9(2.1)).","Traps and snares on land must be chained, cabled, or wired to a tree, grapple, heavy object, or stake (s. 9.1; the Victor Rat Trap is exempt).","Hudson Bay coastline: no bait within 10 km unless permitted or licence conditions allow (s. 6.1); no leghold trap or snare on land within 10 km from September 1 to November 15 (s. 6.1.1).","All traps and snares must be removed before the season closes (s. 10). Every trapped animal must be retrieved (s. 10.1(1)); hides and pelts must not be wasted, abandoned, or allowed to spoil (s. 10.1(2)).","No trapping in Birds Hill Provincial Park, Beaudry Provincial Park, parts of Pembina Valley Provincial Park, or ecological reserves; muskrat in Grant's Lake WMA, and any furbearer, black bear, or wolf in Game Hunting Area 38, only under a special permit (s. 6)."]},"license_summary":{"resident_open_area_licence":"Resident (Open Area) Trapping Licence - $14.50 (2026-27 guide figure, incl. 5% GST and a Fish and Wildlife Enhancement Fund portion). Manitoba residents only: no trapping licences are issued to non-residents. The licence is valid in Open Trapping Area Zones 1-5, and a holder may trap in any OTA zone (the zone and Local Fur Council area are recorded at purchase for harvest tracking). Minimum age 12. First-time trappers must hold a trapper education graduate certificate (see trapper_education).","resident_open_area_licence_treaty":"Resident (Open Area) Licence - Treaty - free. For Treaty/status holders; available through Manitoba elicensing, Conservation Officer Service offices, and most First Nations band offices.","registered_trapline_permit":"Registered Trapline (RTL) Permit - $15.00 (2026-27). Issued through Conservation Officer Service district offices to the lineholder of a registered trapline section; the lineholder holds exclusive harvest rights on their line, and lines are awarded by competition (not sold or inherited). A person may not hold both an RTL permit and an open trapping area licence in the same trapping year (M.R. 245/90 s. 13), except that a landowner/tenant may hold an open area licence for their own land. Helpers may trap a line with the lineholder's written consent while the lineholder is actively trapping.","youth_licence":"Youth Trapping Licence/Permit (ages 12-17 on October 1) - free.","trapper_education":"Mandatory for first-time trappers: a trapper education graduate certificate from a course of at least 9 hours approved by the minister (M.R. 245/90 s. 4), or an equivalent certificate from another jurisdiction. Exam pass mark 80%; courses are usually 2 days or 3 evenings through the Manitoba Trappers Association. Hunter Education does NOT satisfy the requirement. Trappers who obtained a licence or permit before 1990 are exempt; anyone licensed after 1990 without a certificate must complete the course.","special_trapping_area":"Special Trapping Area (STA) harvest is by permit through Conservation Officer Service offices, with eligibility determined by the Conservation Officer for the area. Muskrat in the Southern Special Trapping District, the Northern Special Trapping District (guide only - see known gaps), Oak Hammock Marsh WMA, and Grant's Lake WMA is by special permit; any furbearer, black bear, or wolf in Game Hunting Area 38 is by special permit only (M.R. 245/90 s. 6).","dead_wild_animal_possession_permit":"Dead Wild Animal Possession Permit (Furbearer) - $10.50. Required to keep an accidentally captured furbearer; obtain one from a Conservation Officer as soon as possible after the capture. Subsequent accidental captures of the same species are turned over to the Conservation Officer Service and remain Crown property. Exception: open area trappers may not keep an accidentally taken black bear (except in the Northern Special Trapping District).","export_permit":"Export Permit - $21.00. A provincial export permit is required before shipping raw pelts out of Manitoba (Wildlife Branch, Winnipeg, 431-276-8352, or Conservation Officer Service offices). A federal CITES export permit (Environment and Climate Change Canada) is also required for bobcat, black bear, lynx, river otter, and wolf crossing international borders.","vendor":"Manitoba elicensing (manitobaelicensing.ca; new platform effective April 1, 2026), vendors, and Conservation Officer Service offices. 2026/27 resident trapping licences went on sale September 1, 2026. RTL permits are issued through COS district offices. All fees include 5% GST plus a Fish and Wildlife Enhancement Fund portion and are stated in the guide as subject to change.","harvest_reporting":"Harvest reporting is VOLUNTARY in Manitoba (contrast Ontario's mandatory report). Open area licence holders may complete the Trapper Harvest Survey (available until August 31, 2027) or the Furbearer Harvest Report Form / voluntary online questionnaire at manitobaelicensing.ca. Fur dealers must record all transactions and report by the 10th day after the reporting period; processors report quarterly.","tagging":"Tagging is narrow in Manitoba: a marten, fisher, or river otter taken in the Turtle Mountain Registered Trapline Section (the Southern RTL District) must carry a minister-issued tag or seal on the pelt or unskinned carcass before it is possessed for sale, bought, sold, or disposed of (M.R. 245/90 s. 12).","rights_based_harvest":"Status First Nations people may generally trap for food, traditional, or ceremonial purposes on reserve lands, wildlife management areas, provincial forests, areas of provincial parks where licensed trapping is permitted, unoccupied Crown lands, community pastures with permission, and private land with permission, without a provincial licence, and are not subject to AIHTS equipment restrictions. Pelts taken under rights may not be sold (sale requires a licence and full compliance). Safety and conservation rules still apply, and protected species may not be taken where prohibited (e.g., wolverine in open trapping areas).","defence_of_property":"Under The Wildlife Act s. 46, landowners and occupiers may take furbearers, black bear, and wolves in defence of property without a licence; the take must be reported to a Conservation Officer within 10 days (badgers taken this way must also be reported within 10 days), and pelts are not saleable except under permit."},"seasons_status":null,"seasons_note":null};
window.OPOSSUM_FOOT_CANADA_DATA["NB"] = {"check_interval":{"live_holding":"Restraining, live-holding, leg-hold, box traps and leg snares (excluding drowning sets): 48 hours (Reg. 2023-12 amending Fur Harvesting Reg. s. 4(4.1)).","killing":"Beaver killing traps/drowning sets under an operator's licence: 72 hours (Reg. 2026-22); no interval stated for other killing traps. Nuisance Wildlife Control Operator work: traps/snares every 24 hours, beaver sets every 72 hours.","note":null},"tenure":"No registered trapline system found - Fur Harvester's Licence is zone-based (Wildlife Management Zones 1-27).","trap_id_requirement":"PARTIAL - only holders of a special coyote control permit must affix the permit number to all traps and snares used under it (Fur Harvesting Regulation 84-124 s. 4.1(4)). No general trap-marking requirement for ordinary fur harvesters found. [R2 Item 6]","royalty":"None found in the Fish and Wildlife Act, Fur Harvesting Regulation 84-124, or GNB licence pages. [R2 Item 5]","nuisance_route":"Paid route exists - a Nuisance Wildlife Control Operator's Licence is required to operate (or work for) a nuisance wildlife control enterprise, i.e. removing/relocating nuisance wildlife for consideration (NB Reg 97-141; issued by the Minister; expires Dec 31; records per animal and an annual report due Jan 14). Kill or relocate both allowed, except six rabies-vector species (raccoon, skunk, fox, coyote, groundhog, mink) may not be relocated and must be humanely euthanized; bat work needs a separate permit. Verified in regulation text. [R2 Item 3]","harvest_reporting_and_sealing":"Bobcat, marten and otter carcasses must go to a district office within 5 days after season close, with trapper name, licence number and WMZ of capture - an offence to fail. Bobcat pelts need lock-seal tags attached through lip to eyehole immediately on taking possession; only properly tagged pelts may be possessed/sold. [R1 s.5]","aihts_canada_only":{"canada_wide":"AIHTS in force in Canada since 1 June 1999 (Canada, the EU and Russia are parties; the US is not a party). FIC-certified traps mandatory per Phase 1 lists - killing traps: beaver, Canada lynx & bobcat, fisher, marten, muskrat (on land and underwater), otter, raccoon, weasels/ermine; restraining traps: beaver (cage), bobcat, Canada lynx, raccoon, wolf. Conventional steel-jawed leghold restraining traps on land are effectively banned for AIHTS species. Killing neck snares are NOT AIHTS traps and are not FIC-certified; provinces regulate snares separately. [R1 s.2a]","jurisdiction_specific":"New Brunswick is a FIC Note 1 province (exclusive use of certified restraining traps for raccoon). Secondary reporting puts certified coyote restraining traps mandatory in 2029-30. [R1 s.2a]"},"aihts":{"certified_killing_traps_schedule_a":[{"models_approx":25,"note":"","species":"Beaver"},{"models_approx":19,"note":"Usable only from the Saturday of the second week in November to December 31 (s. 4(4.01)(c)(i)); killing traps are prohibited for bobcat from January 1 to the last day of February.","species":"Bobcat"},{"models_approx":13,"note":"","species":"Fisher"},{"models_approx":16,"note":"","species":"American marten"},{"models_approx":36,"note":"Land use only. Underwater: 'any jaw type trap (body gripping or leg hold) set as a submersion set' qualifies (Schedule A).","species":"Muskrat"},{"models_approx":16,"note":"","species":"River otter"},{"models_approx":31,"note":"","species":"Raccoon"},{"models_approx":26,"note":"Single combined list covering all weasel species.","species":"Weasel"}],"certified_leghold_traps_schedule_a2":[{"models_approx":7,"note":"Includes the Belisle Footsnare #6 and Belisle Selectif and specified Oneida Victor soft-catch/offset-laminated configurations.","species":"Bobcat"}],"certified_live_holding_traps_schedule_a3":[{"models_approx":6,"note":"Cage-type live beaver traps (e.g. Hancock, Comstock swim-through).","species":"Beaver"}],"certified_restraining_traps_schedule_a1":[{"models_approx":5,"note":"Bridger T3, Duffer's Raccoon Trap, Lil Grizz Get'rz, Duke DP Coon Trap, Egg Trap. Required for raccoon trapping October 1-30 (s. 4(4)(f.4)).","species":"Raccoon"}],"models_note":"This pass captured schedule structure and exact model counts per species counted from the consolidated regulation text, not the full model-by-model lists. Full transcription of Schedules A, A.1, A.2 and A.3 (about 150 models) is a defined follow-on task. Certification is not the same as current manufacturing: several certified models are legacy/discontinued. Do not present the certified list as a shopping list without a retailer-availability check, which was not done in this pass.","models_transcribed":false,"nb_schedules_url":"https://laws.gnb.ca/en/document/cr/84-124","no_certified_trap_required":["Mink","Striped skunk","Red squirrel","Varying hare (rabbit)","Coyote and red fox (killing traps prohibited outright; leg-hold restraining traps are regulated by jaw-spread and jaw-modification rules, not by a certified list)"],"note":"New Brunswick implements the AIHTS through N.B. Reg. 84-124 s. 4(4.01)-(4.02) and its own schedules: Schedule A (certified killing traps), Schedule A.1 (certified restraining traps - raccoon), Schedule A.2 (certified leg-hold traps - bobcat), Schedule A.3 (certified live holding traps - beaver). DNRED's Furbearer Harvest Report states that since the 2007 season the regulations have been changed so that only certified traps are allowed for beaver, fisher, marten, raccoon and muskrat, and points trappers to the certified trap list printed in the Hunt & Trap Summary; the regulation's schedules in fact extend certified-trap requirements to otter, weasel and (conditionally) bobcat as well. The schedules track the Fur Institute of Canada national certified-trap list (updated July 22, 2026). AIHTS was agreed in 1997 and ratified by Canada in June 1999; it covers 12 North American species.","source_updated":"2026-07-22","source_url":"https://fur.ca/wp-content/uploads/2026/07/CertifiedTrapsList_FIC_July-22-2026-_EN.pdf","trap_rules":["Only Schedule A killing traps may be used for beaver, raccoon, muskrat, weasel, marten, fisher or otter (Reg. 84-124 s. 4(4.01)(a)).","Killing traps are prohibited for coyote and fox (s. 4(4.01)(b)).","Killing traps for bobcat: Schedule A traps only, and only from the Saturday of the second week in November to December 31; prohibited January 1 to the last day of February (s. 4(4.01)(c)).","Only Schedule A.3 live holding traps may be used for beaver (s. 4(4.02)); only Schedule A.2 leg-hold traps may be used for bobcat (s. 4(4)(f.1)(i.02)); raccoon trapping October 1-30 requires Schedule A.1 restraining traps (s. 4(4)(f.4)).","Leg-hold traps: fox - jaw spread 20 cm or less, no running pole or spring pole set; coyote - jaw spread 20 cm or less, jaws laminated, offset or padded, no running pole or spring pole set; beaver, muskrat, otter and mink - drowning sets only, jaw spread 22 cm or less (s. 4(4)(f.1)).","Toothed traps, deadfalls and hooks are prohibited (s. 4(4)(f)). No trap or snare inside a muskrat house (s. 4(4)(b)). Weasel and squirrel traps must be entirely enclosed in a wooden or metal box with no opening larger than 3.75 cm (s. 4(4)(e.1)).","Mink traps: on the ground within three metres of the water's edge, or a water-base set or drowning set (s. 4(4)(f.2)). Beaver snares from the fourth Sunday of January to the season close must be baited with fresh hardwood and placed entirely underwater (s. 4(4)(f.3)).","Snares (other than power snares) of wire over 0.75 mm diameter must have a locking device (s. 4(4)(d.1)). No setting traps or snares between the close of the fox season and the opening of the muskrat season except for rabbit (s. 4(4)(e)).","Trap check: restraining, live holding, leg hold and box traps and leg snares (excluding drowning sets) at least once every 48 hours (s. 4(4.1))."]},"license_summary":{"carcass_submission":"Every holder of a fur harvester's or minor's fur harvester's licence must deliver the entire skinned carcass (including head and organs) of every bobcat, otter, fisher and marten taken to a district ranger office not later than five days after the last day of the applicable open season; the Minister issues a receipt for each carcass (s. 4.2(1)-(2)).","certified_traps":"Only AIHTS-certified traps may be used where Reg. 84-124 prescribes them: killing traps for beaver, raccoon, muskrat, weasel, marten, fisher and otter must be Schedule A traps (s. 4(4.01)(a)); bobcat killing traps must be Schedule A traps and only from the Saturday of the second week in November to December 31 (s. 4(4.01)(c)); early-season raccoon trapping requires Schedule A.1 restraining traps (s. 4(4)(f.4)); bobcat leg-hold traps must be Schedule A.2 traps; beaver live holding traps must be Schedule A.3 traps (s. 4(4.02)). Killing traps are prohibited for coyote and fox (s. 4(4.01)(b)). See the aihts object.","course":"Before a first fur harvester's licence is issued, the applicant must show proof of (a) a recognized firearm safety and hunter education course (or bow hunter education, if hunting by bow/crossbow) and (b) a recognized trapper education course (s. 4(1.2)). Both course requirements are waived for an applicant born before January 1, 1981 who proves previous holding of the corresponding licence (ss. 4(1.201), 4(1.202)). Minors 12-15 must meet the same course requirements (s. 4(1.11)); a minor 10-11 may hunt, trap or snare only when accompanied at all times by an adult fur harvester licence holder (s. 4(1.12)), and minors under 12 may not carry a firearm (s. 4(4.5)).","export_permits":"An export permit under Fish and Wildlife Act s. 91 for bobcat, otter, fisher or marten pelts is issued only against the carcass receipts tendered - one pelt per receipt (s. 4.2(3)-(4)). Bobcat and river otter are CITES-listed; exporting their pelts from Canada also requires a CITES export permit (Hunt & Trap guide). Parts of fur bearing animals that may be bought, sold, bartered or exported are the claws, teeth, urine, tail, prepared pelt and scent glands of lawfully taken animals (s. 4.3).","fees":"Fees are set in Reg. 84-124 s. 18: fur harvester's licence $43 (under 65) / $22 (65 and over); minor's fur harvester's licence $0; application for a bobcat authorization $9; rabbit licence $8; minor's rabbit licence $0; resident fur trader's licence $37.50; non-resident fur trader's licence $150; resident hide dealer's licence $22.50; non-resident hide dealer's licence $75; replacement licence $5.25. A $5 conservation fee (Wildlife Trust Fund) is added to a fur harvester's licence or rabbit licence at purchase (s. 18.1) - so a rabbit licence costs $13.00 in total, matching the guide. The guide shows the bobcat application as '$9 plus HST'; whether HST applies to the licence fees themselves was not verified in this pass (see known gaps).","fur_harvesters_licence":"A fur harvester's licence (Fish and Wildlife Act s. 83; Reg. 84-124 s. 4(1)(a)) is required to hunt, trap or snare fur bearing animals and to possess or sell pelts. Issued to New Brunswick residents only, 16 years of age or over; NOT issued to non-residents (Hunt & Trap guide). A minor's fur harvester's licence covers ages 10-15 (s. 4(1)(c)). The licence expires annually on July 31 (s. 4(2)(a)); the guide states it is valid from October 1 to July 31 of the following year.","harvest_report":"Reg. 84-124 contains no Ontario-style mandatory season-end harvest report for fur harvesters. Reporting obligations are: the carcass-submission rule for bobcat, otter, fisher and marten (s. 4.2); a licence holder's duty to furnish information and wildlife parts when required by the Minister (s. 4(3)); the raccoon night-hunting permit report due January 31 (s. 13(3)(a)); the special coyote control permit report due within 14 days after the permit expires (s. 4.1(5)); and fur trader / hide dealer record-keeping and periodic reports (ss. 5, 8). DNRED publishes an annual Furbearer Harvest Report compiled from these sources.","hunting_furbearers":"The fur harvester's licence also covers hunting bobcat, fox, skunk, raccoon, coyote, squirrel and rabbit (varying hare) in season (s. 4(1)(a)(i)). Raccoon and skunk may also be hunted under a Bird and Small Game Licence or Deer and Game Bird Licence (Oct. 1 - Dec. 31, no limit). Coyote may also be hunted under a Varmint Licence (March-September) and under a Bear Licence during bear seasons. Hunting with hounds requires Minister-approved hounds and a permit (ss. 13, 15; maximum three hounds for bobcat or fox). Sunday hunting is restricted in New Brunswick under the Hunting Regulation; the general rule was not transcribed into this dataset (see known gaps).","licence_types":"Fur harvester's licence; minor's fur harvester's licence; rabbit licence; minor's rabbit licence; fur trader's licence (resident / non-resident); hide dealer's licence (resident / non-resident). Overlays: bobcat authorization with lock seal bobcat tags (draw); hound hunting permits (ss. 13, 15); special coyote control permit (s. 4.1); possession/cold-storage permits (s. 7).","outdoors_card":"An Outdoors Card number is required to purchase an angling, hunting or trapping licence, to apply to draws, and to register for a Conservation Education course. Registration is one-time and free; the card is not a licence and need not be carried (DNRED Outdoors Card page).","permission":"Unlike Ontario, Reg. 84-124 does not tie the licence to designated land and contains no registered-trapline system: the fur harvester's licence is valid by WMZ anywhere in the province (subject to the zone closures in s. 4(1.1)). No registered trapline / Crown land trapline tenure was found in the Fish and Wildlife Act or Reg. 84-124 in this pass - a negative finding flagged for DNRED confirmation (see known gaps). Traps or snares may not be disturbed by anyone but the owner or a conservation officer (s. 17). Wildlife Refuges and listed Wildlife Management Areas, parks and historical sites are closed to hunting, trapping and snaring (Hunt & Trap guide). Landowner-permission and trespass rules outside Reg. 84-124 were not verified in this pass.","quotas":"There are no bag limits in New Brunswick fur harvesting except rabbit (varying hare): daily 10, possession 20 (s. 4(8)). The one quota-controlled species is bobcat: the Minister sets an annual quota range for each of WMZs 1-25 (and may set zero), and authorizations are allocated by random computer draw so the number of lock seal tags issued falls within the range (s. 4.01(5)-(6)).","report_violation":"Report violations and illegal hunting, fishing and wood theft to Crime Stoppers at 1-800-222-TIPS (8477) or to a local DNRED office (DNRED 'Report Violations' page; the program is known as Target Poaching).","tagging":"Bobcat pelts must be tagged immediately on killing (hunting) or on taking possession (trapping/snaring) with a previously unused lock seal bobcat tag issued to that person, inserted through the eye hole and mouth of the pelt with the locking mechanism fully engaged (s. 4.02). Possession of an untagged bobcat pelt is prohibited. No other furbearer requires a pelt tag in Reg. 84-124.","trap_check":"Every restraining trap, live holding trap, leg hold trap, box trap or leg snare - excluding drowning sets - must be checked at least once every 48 hours after setting, and any wildlife taken must be removed immediately (s. 4(4.1)). All traps and snares must be removed not later than sunset on the last day of the open season (s. 4(5)). No person may possess a trap or snare in a resort of wildlife in a WMZ more than 48 hours before the season opens or more than 48 hours after it ends (s. 4(4.2)).","where_to_buy":"Licences are available through the Fish and Wildlife Licensing System at gnb.ca/fishwildlife, from authorized vendors, and at all Service New Brunswick centres (Hunt & Trap guide).","zones":"Seasons are keyed to Wildlife Management Zones (WMZs) 1-27, established under s. 12 of the Hunting Regulation (N.B. Reg. 84-133) and adopted for fur harvesting by Reg. 84-124 s. 3. Zone groupings used by Schedule B: 1-27 (province-wide), 1-12 / 13-27 (water furbearers), 1-26 (coyote/fox), 1-12 / 13-26 (coyote/fox snaring), 1-25 (bobcat), 1-12 / 13-25 (bobcat snaring), and 1-13, 15-17, 20 / 14, 18, 19, 21-27 (fisher/marten/skunk). WMZ 27 is Grand Manan Island."},"seasons_status":null,"seasons_note":null};
window.OPOSSUM_FOOT_CANADA_DATA["NL"] = {"check_interval":{"live_holding":"Live-holding devices on land: daily (Trapping Order s. 7(1)); restraining (live) neck snares for fox/coyote/lynx: 24-hour check per the guide.","killing":"No interval for killing traps found.","note":null},"tenure":"Beaver traplines on the Island (vacant lines go on a general areas list for the season) plus general trapping by Fur Management Areas/Zones, split Island / Labrador North / Labrador South.","trap_id_requirement":"None found - no trap owner-ID marking requirement in the sources searched (follow-up pass, Nov 17); identification runs through licence/tenure and pelt seals instead.","royalty":"None in force - Wild Life Act s. 7(1)(d) gives the Minister power to prescribe royalties, but none is prescribed in the Wild Life Regulations or the 2026-27 guide. [R2 Item 5]","nuisance_route":"Case-by-case only - a Permit to Destroy Problem Animals (Dept. of Forestry, Agriculture and Lands) is required to destroy wildlife interfering with farm crops, operations or dwellings when other mitigation fails; kill only, no relocation route stated. Livestock Protection from Coyote permits are for producers only. Whether a hired trapper may hold the destroy permit is not stated - unconfirmed. [R2 Item 3]","harvest_reporting_and_sealing":"All Island lynx must be registered and skins stamped (by Feb 9, 2027 for 2026-27); Labrador trappers submit wolf skull or lower jaw (by May 14, 2027). [R1 s.5]","aihts_canada_only":{"canada_wide":"AIHTS in force in Canada since 1 June 1999 (Canada, the EU and Russia are parties; the US is not a party). FIC-certified traps mandatory per Phase 1 lists - killing traps: beaver, Canada lynx & bobcat, fisher, marten, muskrat (on land and underwater), otter, raccoon, weasels/ermine; restraining traps: beaver (cage), bobcat, Canada lynx, raccoon, wolf. Conventional steel-jawed leghold restraining traps on land are effectively banned for AIHTS species. Killing neck snares are NOT AIHTS traps and are not FIC-certified; provinces regulate snares separately. [R1 s.2a]","jurisdiction_specific":"From 2029-30 only certified restraining traps may be used for coyote; killing neck snares remain permitted with breakaway devices. [R1 s.2a]"},"aihts":{"canada_aihts_species_in_province":["Beaver","Ermine (weasel)","Coyote","Canada lynx","American marten","Muskrat","River otter","Gray wolf"],"certified_killing_traps_schedule_c_part_a":[{"models_approx":25,"note":"NLR 71/18, Schedule C, Part A(a)(i), as replaced by NLR 42/26.","species":"Beaver"},{"models_approx":19,"note":"NLR 71/18, Schedule C, Part A(a)(ii).","species":"American marten"},{"models_approx":36,"note":"NLR 71/18, Schedule C, Part A(a)(iii). Underwater, any jaw-type trap set as a submersion set may be used instead.","species":"Muskrat (on land)"},{"models_approx":26,"note":"NLR 71/18, Schedule C, Part A(a)(iv).","species":"Ermine (weasel)"},{"models_approx":18,"note":"NLR 71/18, Schedule C, Part A(a)(v).","species":"Canada lynx"},{"models_approx":17,"note":"NLR 71/18, Schedule C, Part A(a)(vi).","species":"River otter"}],"certified_restraining_traps_schedule_c_part_b":[{"models_approx":6,"note":"Cage traps only. NLR 71/18, Schedule C, Part B(b)(i).","species":"Beaver"},{"models_approx":14,"note":"NLR 71/18, Schedule C, Part B(b)(ii).","species":"Gray wolf"},{"models_approx":5,"note":"NLR 71/18, Schedule C, Part B(b)(iii).","species":"Canada lynx"}],"coyote_certified_traps":{"mandatory_from":"2029-30 season","models_listed_in_guide":22,"note":"The 2026-27 guide lists 22 certified restraining trap models for coyote from the Fur Institute of Canada implementation schedule (September 2025); they become mandatory in the 2029-30 season. Until then, currently permitted traps and killing neck snares remain legal for coyote."},"no_certified_trap_required":["American mink","Red fox (coloured)","Arctic fox (white)","Red squirrel","Black bear","Coyote (restraining traps, until the 2029-30 season)"],"note":"Newfoundland and Labrador implements the Agreement on International Humane Trapping Standards in law: NLR 71/18, s. 3 requires traps for beaver, muskrat, marten, lynx, weasel (ermine) and otter, and restraining traps for beaver, lynx and wolf, to be models listed in Schedule C of that Order — a provincial list that tracks the Fur Institute of Canada certified trap list. The guide states the AIHTS applies to eight species in the province (beaver, ermine/weasel, coyote, lynx, marten, muskrat, otter, wolf) and does not apply to mink, fox or squirrel. Sufficient numbers of killing traps have not yet been certified for wolf or coyote, so currently permitted devices (including locking neck snares) remain legal for those two species. Model counts are structural counts of Schedule C as replaced by NLR 42/26 in 2026; the full model-by-model list was not transcribed in this pass — see the Fur Institute of Canada certified trap list (July 22, 2026).","trap_rules":["Killing neck snares set on land must have a locking device; on the Island of Newfoundland they must also have a breakaway device that disassembles the snare loop or releases the loop when a static force of 340 kg or more is applied (NLR 71/18, s. 4, as amended by NLR 42/26).","Live holding devices set on land must be checked once per day (NLR 71/18, s. 7(1)). Restraining neck snares on the Island must have a breakaway device releasing at 340 kg or less, except snares set completely under water or as part of a submersion set (s. 7(2)).","Foothold traps for beaver, muskrat, otter or mink must be set as submersion sets (NLR 71/18, s. 5(1)). Foothold traps for coyote or wolf must have a minimum 5 mm space between the jaws when fully closed, rubber-like jaw pads, or jaws at least 9 mm thick (s. 5(2)).","Killing traps must not have metal teeth, serrated edges or hooks on their jaws, and spring poles and foothold traps set in trees or on poles are prohibited unless the trap is set as a killing trap (NLR 71/18, s. 6).","Marten protection: in Category One areas only Schedule D traps may be used, with no land-based traps or snares and no small game snaring; in Category Two areas only Schedule E devices may be used (NLR 71/18, s. 3(2), Schedules D and E). The Little Grand Lake Provisional Ecological Reserve is closed to all trapping except beaver.","Restraining neck snares for fox, coyote and lynx in Labrador marten-recovery areas: cable at least 3/32 inch, a 360-degree swivel, a stop limiting the loop to a minimum circumference of eight inches, fastened to an immovable object, no drags, checked daily, and a breakaway device releasing at 340 kg or less (NLR 71/18, s. 3(3)-(4)).","Small game snaring is restricted to 22-gauge brass wire or six-strand braided picture cord (2026-27 guide)."]},"license_summary":{"applications":"Applications and payment are online only through the Wildlife Information Management System (WIMS) at wildlife.gov.nl.ca. To receive a licence before the trapping season opens, applications and payments must be received by August 28, 2026. Beaver trapline licence renewals must be received by October 5, 2026 or the trapline may be forfeited. Trapping licences are downloaded and printed — they are no longer mailed.","certified_traps":"Newfoundland and Labrador adopts the AIHTS certified-trap system in law: traps for beaver, muskrat, marten, lynx, weasel (ermine) and otter, and restraining traps for beaver, lynx and wolf, must be models listed in Schedule C of NLR 71/18, which mirrors the Fur Institute of Canada certified trap list. Certified restraining traps for coyote become mandatory in the 2029-30 season. See the aihts block.","course":"All new trappers must complete the Trapper Education Course. A trapper who uses firearms must also have completed the Canadian Firearms Safety Course and the Hunter Education Course, hold an Outdoor Identification Card, and hold a valid General Trapper's Licence. Completing the Trapper Education Course after August 21, 2026 does not guarantee a trapper's licence for the 2026-27 season.","fees":"From the Licence Fees table of the 2025-26 Hunting and Trapping Guide — the 2026-27 web guide carries no fee table, and these fees are unchanged since 2015-16 (see verification.known_gaps): General Trapper's Licence $15.00, senior (age 65+) $9.75; Beaver Trapline Licence or Trapper's Beaver Licence, Island $15.00, senior $9.75. Prices do not include HST; licences purchased through vendor outlets or Government Service Centres carry an additional $3.00 fee. Trapper Education Course fees: adults $150, age 17 and under $80 (2026-27 guide).","harvest_report":"Every holder of a trapper's licence must furnish a return to the Wildlife Division on or before June 30, setting out the number and kinds of fur bearing animals taken during the licence's validity (Wild Life Regulations, s. 24(1)); returns may be filed online through WIMS. The guide's Regulation Summaries state that small game, coyote and trapping returns must be submitted within seven days of the season closing date — the two statements are both carried here and flagged in verification.known_gaps. Island lynx must be registered and the pelt stamped on or before February 9, 2027; the skull or lower jawbone of each wolf taken must be surrendered on or before May 14, 2027; beaver pelts must be pelted and stamped within 14 days after the season closes.","labrador_inuit":"Labrador Inuit Settlement Area (LISA): before a non-Inuit resident of Labrador living outside LISA may trap in LISA, they must demonstrate that they held a commercial trapping licence on June 25, 2001 and trapped there traditionally; a non-Inuit resident of Labrador living inside LISA must demonstrate they held a commercial trapping licence on December 1, 2005, or obtain the consent of the Nunatsiavut Government (2026-27 guide).","licence_types":"General Trapper's Licence (furbearers except beaver); Trapper's Beaver Licence; Beaver Trapline Licence (Island only — an assigned trapline in a Beaver Management Area); Black Bear Licence, with a trapper's licence to take black bear by trapping; combined Small Game/Coyote/Wolf Licence (the shooting seasons for coyote, wolf, red squirrel and other small game); a licence to take one wolf by shooting (Wild Life Regulations, s. 15); Fur Export Licence plus a Fur Export Permit for each shipment (required to sell fur outside the province).","permission":"Trappers must have the permission of the landowner before setting traps or snares on private land (2026-27 guide).","report_violation":"Report Poaching — Resource Enforcement Division, Department of Forestry, Agriculture and Lands: 1-877-820-0999 (toll-free, 24 hours a day, anonymous). Online reporting: gov.nl.ca/feedback/report-poaching/ (Stop Poaching).","residency":"Trapping is residents-only: a non-resident shall not be issued a trapper's licence, a trapper's beaver licence or a beaver trapline licence (Wild Life Regulations, s. 10(4)), and it is an offence under the Wild Life Act and Regulations to apply for a resident licence if you are not a resident of Newfoundland and Labrador (WIMS notice).","tagging":"Traps used on a beaver trapline must be tagged with a metal tag bearing the holder's licence number (Wild Life Regulations, s. 27(11)). Island lynx pelts are stamped at registration; beaver pelts must be pelted and stamped within 14 days after the season closes (s. 28).","trap_check":"Live holding devices set on land must be checked once per day (NLR 71/18, s. 7(1)). Restraining neck snares for fox, coyote and lynx in marten-recovery areas must be checked daily (s. 3(4)). Black bear Aldrich foot snares must be checked daily (guide). No general check interval for killing traps or killing snares was found in NLR 71/18.","trapping_licence":"General Trapper's Licence — authorizes the holder to take or kill fur bearing animals except beaver (Wild Life Regulations, CNLR 1156/96, s. 10(1)(a)). Beaver requires a separate Trapper's Beaver Licence or, on the Island, a Beaver Trapline Licence, and a person may not hold both beaver licences at the same time (s. 27(7)). Licences must be carried on the person while trapping (s. 18).","youth":"A youth who is 12 years of age may hold licences to shoot small game, coyote and wolf, and to shoot or trap furbearers; big game licences start at age 16. Youth 12 to under 16 need written parental or guardian consent for a licence to shoot fur-bearing animals; no consent is required for a General Trapper's Licence for youth under 12, or for a licence that does not involve a firearm (guide, Youth Hunting and Trapping Licences). Designated Adult supervision rules apply to youth using firearms."},"seasons_status":null,"seasons_note":null};
window.OPOSSUM_FOOT_CANADA_DATA["NS"] = {"check_interval":{"live_holding":"Daily - failing to check a snare or trap at least once every day is an offence (Fur Harvesting Regulations s. 11(9)); bear snares also daily (s. 10(1)(c)).","killing":"Daily - the rule covers snares and traps generally, unlike most provinces.","note":null},"tenure":"No trapline tenure - Fur Harvester Licence plus Fur Harvesters Certificate.","trap_id_requirement":"REQUIRED - every trap or snare for a fur-bearing animal must be clearly marked with the trapper's TIN (Trap Identification Number) (Fur Harvesting Regulations s. 11(19), in force since Oct 15, 2006). Exceptions: red squirrel sets and nuisance trapping; traps marked with a partner's TIN may be tended by that partner. Verified in regulation text. [R2 Item 6]","royalty":"None - the Fur Harvesting Regulations (consolidation amended to Jan 26, 2026) contain no royalty. [R2 Item 5]","nuisance_route":"Paid route exists - licensed Nuisance Wildlife Operator (defined as a person who traps/kills/frightens/excludes nuisance wildlife 'for compensation or reward'; the closest Canadian analogue to a US NWCO licence), plus a free Nuisance Wildlife Permit (Wildlife Act s. 28) issued same-day to an owner/occupier authorizing them or their agents. [R1 s.4]","harvest_reporting_and_sealing":"Hunter/fur-harvester information returns are mandatory - failing to submit is an offence. The regulations also provide for stamping of pelts. [R1 s.5]","aihts_canada_only":{"canada_wide":"AIHTS in force in Canada since 1 June 1999 (Canada, the EU and Russia are parties; the US is not a party). FIC-certified traps mandatory per Phase 1 lists - killing traps: beaver, Canada lynx & bobcat, fisher, marten, muskrat (on land and underwater), otter, raccoon, weasels/ermine; restraining traps: beaver (cage), bobcat, Canada lynx, raccoon, wolf. Conventional steel-jawed leghold restraining traps on land are effectively banned for AIHTS species. Killing neck snares are NOT AIHTS traps and are not FIC-certified; provinces regulate snares separately. [R1 s.2a]","jurisdiction_specific":"Certified coyote restraining traps and raccoon cage/box traps mandatory from 2028-29 (provincial notice). Nova Scotia is also a FIC Note 1 province for raccoon restraining traps. [R1 s.2a]"},"aihts":{"certified_killing_traps_schedule_1":[{"models_approx":25,"note":"Schedule A of the Fur Harvesting Regulations.","species":"Beaver"},{"models_approx":19,"note":"Schedule A lists 'Bobcat and Lynx' as one combined list.","species":"Bobcat"},{"models_approx":19,"note":"Same combined 'Bobcat and Lynx' list as bobcat. Lynx has NO open season in Nova Scotia - the listing is a legacy of the national certified list.","species":"Canada lynx"},{"models_approx":13,"note":"Fisher has NO open season in Nova Scotia - the listing is a legacy of the national certified list.","species":"Fisher"},{"models_approx":37,"note":"On land, only Schedule A muskrat traps may be used as body-grippers; underwater, any jaw-type submersion set is permitted (s. 11(21)).","species":"Muskrat"},{"models_approx":16,"note":"","species":"River otter"},{"models_approx":32,"note":"","species":"Raccoon"},{"models_approx":26,"note":"Covers the weasel species present in Nova Scotia.","species":"Weasel"}],"certified_restraining_traps_schedule_2":[{"models_approx":6,"note":"Cage/live beaver traps ('beaver restraining traps', s. 11(22)).","species":"Beaver"},{"models_approx":7,"note":"Includes Belisle footsnares and specified Oneida Victor soft-catch/offset-laminated leghold configurations.","species":"Bobcat"},{"models_approx":5,"note":"Lynx has NO open season in Nova Scotia - legacy listing.","species":"Canada lynx"},{"models_approx":5,"note":"Foot-encapsulating traps (Bridger T3, Duffer, Duke DP, Egg Trap, Lil' Grizz Get'rz). Mandatory for raccoon foothold sets (s. 11(14)(d)).","species":"Raccoon"}],"models_note":"This pass captured schedule structure and model counts per species from Schedules A and B of the Fur Harvesting Regulations (as updated by N.S. Reg. 25/2026), not the full model-by-model list. Full transcription is a defined follow-on task (see the scoping report). Certification is not the same as current manufacturing: several certified models are legacy/discontinued. Do not present the certified list as a shopping list without a retailer-availability check. That check was not done in this pass.","models_transcribed":false,"no_certified_trap_required":["Mink","Red fox","Striped skunk","Red squirrel","Coyote (Phase 2 - certified restraining traps certified nationally but not yet mandatory; Nova Scotia has announced mandatory AIHTS-certified traps for live capture of coyotes from the 2028-29 season)","Raccoon cage/box traps (Phase 2 - mandatory in Nova Scotia from the 2028-29 season per the 2026 Summary Trap Compliance Notice)"],"note":"Nova Scotia adopts the national AIHTS certification (the Canadian Trap Certification Program, administered by the Fur Institute of Canada) by embedding the certified lists in its own regulation as Schedule A (killing traps) and Schedule B (restraining traps) of the Fur Harvesting Regulations. The regulation schedules - not the live FIC web list - are the legal lists in Nova Scotia, and the two are close but not identical (see verification.known_gaps). The 2026 Summary's 'Approved traps' section states: 'Certain trap types must meet the requirements of the Agreement on International Humane Trapping Standards (AIHTS). Approved traps are updated periodically. Check online for an up-to-date list: fur.ca/certified-traps/.'","ns_schedules_url":"https://www.novascotia.ca/Just/Regulations/regs/wifurhrv.htm","source_updated":"July 22, 2026","source_url":"https://fur.ca/wp-content/uploads/2026/07/CertifiedTrapsList_FIC_July-22-2026-_EN.pdf"},"license_summary":{"accidental_catch":"A person who accidentally catches a fur-bearing animal they are not entitled to must forthwith release it alive, OR report it immediately to the Department before removing it from the trap site, OR complete an Accidental Harvest Form before removing it (Fur Harvesting Regulations s. 11(12)). The 2026 Summary: report immediately to a local DNR office (office hours) or 1-800-565-2224 after hours, and complete the Accidental Harvest Form (booklet p. 57). One accidentally caught fisher's pelt may be kept (carcass turned in, pelt stamped); raccoons taken accidentally in fox/coyote sets before the raccoon season may be kept (ss. 6(6)-(7)).","certified_traps":"Body-gripping traps for beaver, fisher, raccoon, weasel, otter, lynx and bobcat may only be traps listed in Schedule A of the Fur Harvesting Regulations as certified killing traps for that species; muskrat body-grippers only underwater as submersion sets or, on land, if Schedule A-listed for muskrat (ss. 11(20)-(21)). Beaver restraining traps must be Schedule B-listed (s. 11(22)); foot-encapsulating traps for raccoon and leghold traps for lynx/bobcat must be Schedule B-listed restraining traps (s. 11(14)(d),(g)). The schedules are headed 'Certified under the Canadian Trap Certification Program' - the national AIHTS certification administered by the Fur Institute of Canada; the 2026 Summary directs trappers to fur.ca/certified-traps/ for the up-to-date list. See the 'aihts' section of this dataset.","course":"Furharvester Education Course - mandatory for all first-time fur harvesters since 1986; final examination must be passed with a score of 90% or better. Delivered in person only; fee $65 + HST; registration through HuntNS.ca; courses usually run late summer/early fall and are managed by the Department's Hunter Education Coordinator in cooperation with the Trappers' Association of Nova Scotia (TANS). Completion gives FT (Furharvester Trained) certification; FQ (Furharvester Qualified) is the grandfathered equivalent. FQ is maintained by buying at least one Fur Harvester Stamp every four years - otherwise the course must be retaken before a licence can be issued (Fur Harvesting Regulations s. 3(1A)). FT certification earned outside Nova Scotia is not transferable. An optional hands-on Trapper Education Workshop is held about once a year by TANS.","fees":"Fur Harvesters Stamp $21.17 + HST (Fur Harvesting Regulations s. 3(3); 2026 Summary p. 8 - 'Fur Harvester Resident $21.17 + HST', DNR offices only). Wildlife Habitat Stamp (base licence) $5.15. Bear Snaring stamp (resident) $26.57 + HST, resident seniors 65+ $0.00; Bear Hunting stamp (resident) $26.57 + HST. Wildlife Resources Card $6.25 + HST for a new or replacement card (Department's Wildlife Resources Card page).","harvest_report":"Mandatory Fur Harvester Report: every Fur Harvester's Licence holder must submit the Fur Harvester Report Form plus fur-buyer receipt slips by April 15 (April 15, 2027 for 2026-27) - even if they did not trap. Report online at HuntNS.ca, by email (HuntNS@novascotia.ca), or on paper to a local DNR office (Fur Harvesting Regulations s. 13; 2026 Summary pp. 20, 49). Failure to report carries penalties starting from $180 and loss of the opportunity to hold a licence in subsequent years. Report harvest by county, sets and trap nights; pelts retained past April 15 are registered in the report's 'Kept' column - no other permit is needed to retain furs so registered. Bear licence holders must file their information return within 2 weeks of season end (Dec 19, 2026) and submit the lower jaw or skull of any bear killed (Bear Harvesting Regulations s. 11).","hunting_furbearers":"Under a Fur Harvester's Licence, bobcat, fox, raccoon, weasel and red squirrel have hunting as well as trapping seasons (Fur Harvesting Regulations s. 6(3)). Beaver, muskrat, mink and otter may NOT be taken by firearm or bow unless the animal is confined by a trap (s. 11(1)). Coyote and red squirrel are also 'other harvestable wildlife' under the General Wildlife Regulations, huntable on a base licence alone (coyote year-round; red squirrel Nov 1 - Feb 28). Raccoon night hunting requires a Raccoon Dog Night Training/Hunting Permit.","licence_types":"Fur Harvester's Licence (residents only; non-residents may not take, trap or possess fur-bearing animals except under a Non-Resident Furbuyers Licence - s. 4). Apprentice registration: a resident under 19 may set and tend traps under the immediate supervision of a licensed fur harvester 19+, identified in writing to the Department; the apprentice's harvest counts toward the supervisor's bag limit (s. 3(2)). Also relevant: Resident Bear Snaring Licence (requires FQ/FT certification) and the base licence (Wildlife Habitat Stamp) alone for 'other harvestable wildlife' hunting (coyote, red squirrel). Trapping in partnership is allowed after written notice to the Department; partners may tend traps marked with a partner's TIN (s. 11A).","licensing_transition":"Nova Scotia is modernizing licensing through the HuntNS online system (HuntNS.ca): certifications (HT, B, CT, FT, FQ, GT, N) now appear on the client's HuntNS profile, and harvest reports are filed online. Fur Harvester and Bear Snaring licences are still sold at DNR offices only (2026 Summary p. 8). No cutover date affecting the Fur Harvester's Licence was announced in the 2026 Summary.","pelt_stamping":"Otter and fisher are mandatory turn-in species in 2026-27: turn in the whole skinned carcass to the local DNR district office, exhibit the pelt for stamping, and declare your Wildlife Resources Client Number, date of capture, location of capture and method of kill (Fur Harvesting Regulations s. 10; 2026 Summary pp. 21, 56). To sell an otter or fisher in the round (unskinned), first exhibit the animal at the district office and obtain a Round Permit. No furbuyer may possess a pelt required to be stamped unless it is stamped. Marten and lynx (accidental catches): entire animal must be turned in. Bear: lower jaw or full skull.","permission":"Trap setbacks (Fur Harvesting Regulations s. 11(3)-(4)): no trap or snare within 274 m of a dwelling, school, playground, athletic field or place of business, or within 182 m of those places plus golf courses, woods operations, agricultural and public buildings, except as the regulation provides (owner/occupier permission, conservation-officer written authorization for nuisance trapping, and exemptions for box traps, under-ice snares, submarine traps, hooded rat traps, and - within 274 m with landowner permission - cable restraints, foot-encapsulating traps, padded modified legholds and small submerged body-grippers, which must still be 182 m from other protected places). Traps/snares are also restricted within 15 m of trails and highways (s. 11(5)-(5C); K-class roads excepted). Do not set traps on posted private forest land where the owner/occupier has posted notice prohibiting trapping (snowshoe hare snares excepted). Dens and beaver dams may not be damaged or destroyed.","possession":"Pelt possession under a Fur Harvester's Licence: beaver, otter, mink, muskrat, weasel, fisher and bobcat pelts Nov 1 - Apr 15; fox and raccoon pelts Oct 15 - Apr 15; coyote, skunk and red squirrel pelts year-round. Pelts may be kept beyond the possession date if registered in the 'Kept' column of the Fur Harvester Report (Fur Harvesting Regulations s. 7; 2026 Summary pp. 55-56). An export permit from DNR is required to ship furs out of the province (not required when sold or consigned to a licensed Nova Scotia furbuyer). Bobcat, otter and bear are CITES-listed - exporting out of Canada may require a CITES Export Permit.","quotas":"No quotas in Nova Scotia. Harvest is governed by per-licence bag limits only: bobcat 5 per licence; beaver 30 per licence in Zone 1 and 20 per licence in Zones 2-4 (by the zone of the licence holder's permanent residence); bear 1 (hunting) / 2 (snaring). There is no bag limit for muskrat, fox, mink, otter, skunk, red squirrel, coyote, weasel or raccoon (Fur Harvesting Regulations s. 9).","report_violation":"Report illegal hunting or trapping to a local DNR office or by phone at 1-800-565-2224 (2026 Summary cover and p. 58). Online: novascotia.ca/natr/enforcement/reportapoacher.asp.","sunday_hunting":"Sunday hunting is permitted only on designated Sundays: in 2026 the window was extended to the first Sunday immediately following October 1 through the last Sunday in December, for all harvestable species (2026 Summary p. 10). Traps may be checked and trapped animals dispatched on Sundays - a Fur Harvester's Licence holder may use a .22 calibre or smaller rimfire rifle during the fur harvesting season, including Sundays, to dispatch animals in traps (Firearm and Bow Regulations s. 7(1)). The bear snaring season expressly includes Sundays.","trap_check":"Every trap or snare designed to hold an animal alive - including cable restraints - must be examined at least once every day ('day' = 12:01 a.m. to 11:59 p.m.) (Fur Harvesting Regulations s. 11(9)). Bear snares must likewise be examined at least once every day (Bear Harvesting Regulations s. 10(1B)).","trap_marking":"Since October 15, 2006, every trap or snare set for a fur-bearing animal must be clearly marked with the setter's TIN (trap identification number); the 2026 Summary directs trappers to mark their Wildlife Resources Client Number permanently on traps and snares. Exempt: traps/snares set for red squirrel, and nuisance-wildlife sets under the General Wildlife Regulations (Fur Harvesting Regulations s. 11(19); 2026 Summary p. 50).","trapping_licence":"A Fur Harvester's Licence - a valid base licence (Wildlife Habitat Stamp) with a Fur Harvesters Stamp affixed - is required to trap, snare, hunt, shoot or possess any wild furbearer in Nova Scotia (Fur Harvesting Regulations ss. 2, 3). Issued only to Nova Scotia residents who are 16 or older and hold a Wildlife Resources Client Number with FQ or FT certification. Sold at DNR offices only. The licence expires on April 15 following issuance (s. 3(4)); licences can generally be purchased any time after August 1."},"seasons_status":null,"seasons_note":null};
window.OPOSSUM_FOOT_CANADA_DATA["NT"] = {"check_interval":{"live_holding":"Restraining traps (live-hold soft catch or leg snare): at least once every 72 hours (GNWT official trapping page; GNWT Summary of Hunting and Trapping Regulations).","killing":"No interval stated for killing traps or killing snares.","note":"Confidence: official guide / government page - the underlying Trapping Regulations text was not located online (R2 Item 1). Supersedes R1, which found no NWT interval."},"tenure":"Registered trapping areas / registered group trapping areas in some areas; otherwise rights-based harvesting plus Special Trapping Licences for non-rights holders (typically only at an Aboriginal community's request).","trap_id_requirement":"None found - no trap owner-ID marking requirement in the sources searched (follow-up pass, Nov 17); identification runs through licence/tenure and pelt seals instead.","royalty":"None found - the Wildlife Fees Regulations R-114-2014 list fees only and the Wildlife Act has no royalty provision; the GNWT instead pays trappers through the Genuine Mackenzie Valley Fur Program. [R2 Item 5]","nuisance_route":"None found - Wildlife Act ss. 55-56 self-help (chase wildlife away; kill if necessary to prevent injury/death or property damage); problem-wildlife response is officer-led (Renewable Resource Officers). No NWCO licence or paid-trapper program found. [R2 Item 3]","harvest_reporting_and_sealing":null,"aihts_canada_only":{"canada_wide":"AIHTS in force in Canada since 1 June 1999 (Canada, the EU and Russia are parties; the US is not a party). FIC-certified traps mandatory per Phase 1 lists - killing traps: beaver, Canada lynx & bobcat, fisher, marten, muskrat (on land and underwater), otter, raccoon, weasels/ermine; restraining traps: beaver (cage), bobcat, Canada lynx, raccoon, wolf. Conventional steel-jawed leghold restraining traps on land are effectively banned for AIHTS species. Killing neck snares are NOT AIHTS traps and are not FIC-certified; provinces regulate snares separately. [R1 s.2a]","jurisdiction_specific":null},"aihts":{"certified_killing_traps_schedule_1":[],"certified_restraining_traps_schedule_2":[],"models_note":"The NWT publishes NO territorial schedules of certified traps equivalent to Ontario's O. Reg. 667/98 Schedules 1 and 2, so no per-species model counts are recorded here — entering Ontario's counts would misstate the NWT position. The operative list is the Fur Institute of Canada's national certified-trap list, which the NWT points trappers to. Model-by-model transcription of the FIC list for the NWT species set is a defined follow-on task.","models_transcribed":false,"no_certified_trap_required":[],"note":"The NWT implements the AIHTS by requiring certified traps territory-wide: the GNWT Summary states 'It is unlawful for any person to use traps not listed in the regulations. Only approved certified traps listed in the Agreement on International Humane Trapping Standards may be used in the NWT.' The Genuine Mackenzie Valley Fur program also complies with the AIHTS. Unlike Ontario, the requirement is not species-scheduled in published territorial material — it reads as a blanket certified-traps rule for trapping. AIHTS was agreed in 1997 and ratified by Canada in June 1999; the FIC maintains the national certified list.","ontario_schedules_url":"","source_updated":"2026-07-22","source_url":"https://fur.ca/wp-content/uploads/2026/07/CertifiedTrapsList_FIC_July-22-2026-_EN.pdf","trap_rules":["Only AIHTS-certified traps may be used in the NWT; it is unlawful to use traps not listed in the regulations (GNWT Summary, Wildlife Regulation notice).","Live-hold restraining traps (soft-catch traps / leg snares) must be checked at least once every 72 hours (ECC).","Trapping equipment must not be set before the first day of a season and must be removed or rendered harmless by the last day of the season (GNWT Summary).","Pelt wastage is an offence for bear*, beaver*, coyote, ermine, fisher, fox, least weasel, lynx, marten, mink, muskrat*, otter, skunk, wolf and wolverine (*pelts may be discarded where the animal was harvested for meat)."]},"license_summary":{"certified_traps":"Only AIHTS-certified traps may be used in the NWT: the GNWT Summary states it is unlawful for any person to use traps not listed in the regulations, and that only certified traps listed under the Agreement on International Humane Trapping Standards may be used. See the 'aihts' section of this dataset.","export":"A wildlife export permit is required to export wildlife from the NWT (no fee under the Fees Regulations); non-residents require one for big game. A federal CITES export permit is required to export CITES-listed species (including wolf, lynx and otter) from Canada.","fees_not_verified":"The General Hunting Licence fee itself was NOT verified from the Fees Regulations schedule in this pass. Do not quote a GHL price until the schedule is read directly. See verification.known_gaps.","fees_verified":"From the Wildlife Fees Regulations, R-114-2014 (consolidation): registered trapping area licence $24; membership in a registered group trapping area — no fee; authorization to trap furbearers under a Special Harvester Licence $24; small game authorization on a hunting licence $24 (resident/SHL), $48 (non-resident), $119 (non-resident alien); wildlife export permit — no fee; fur dealer licence $475, renewal $238.","gmvf_program":"The Genuine Mackenzie Valley Fur (GMVF) program markets NWT wild fur, complies with the AIHTS, and takes fur in through Renewable Resource Officers. The GNWT also publishes an annual NWT Trapper's calendar and a GMVF Trapper Education Manual.","harvest_reporting":"No Ontario-style mandatory season-end harvest report was found in published GNWT material in this pass. ECC runs carcass and sample collections and GMVF fur is submitted through Renewable Resource Officers; whether a formal trapper harvest-reporting duty exists in the Trapping Regulations is unverified — see known_gaps.","hunter_education":"As of January 1, 2020, all resident and non-resident hunters must complete Hunter Education training before being issued a hunting licence in the NWT, unless exempt under the regulations (GNWT Summary).","land_claims":"Land-claim settlement regions layer over territorial law: the Inuvialuit Settlement Region, Gwich'in Settlement Area, Sahtu Settlement Area, Tłı̨chǫ lands, and the Dehcho (no final agreement). A licensed trapper may not harvest the following without permission from the land-claim organization: ground squirrel, red squirrel, marmot and hare in the Inuvialuit Settlement Region; ground squirrel, red squirrel and marmot in the Gwich'in Settlement Area; red squirrel and marmot in the Sahtu Settlement Area; woodchuck and red squirrel on Tłı̨chǫ lands (ECC). Co-management boards (WMAC, Gwich'in Renewable Resources Board, Sahtu Renewable Resources Board, Wek'èezhı̀ı Renewable Resources Board) and local Hunters and Trappers Committees / Renewable Resources Councils recommend or set conditions that the territorial regulation alone does not show.","licence_types":"General Hunting Licence (GHL) — an Aboriginal person who is a member or eligible to be a member of an NWT organization listed in the regulations; Resident Hunting Licence (Canadian citizen or landed immigrant resident in the NWT for 12 continuous months); Non-resident and Non-resident Alien Hunting Licences; Special Harvester Licence (SHL). Wildlife Act s. 45(1): no person shall trap furbearers unless authorized by a general hunting licence, a special harvester licence or a permit — subject to the s. 17 rights exception.","registered_trapping_areas":"Registered trapping areas and registered group trapping areas carry exclusive trapping rights for the holder or members. Several Summary season rows are specific to the Fort Good Hope Registered Group Trapping Area (FGH RGTA) and are modelled as their own season rows.","rights_based_harvest":"A person exercising an Aboriginal or treaty right needs NO licence to trap in their traditional area, and there are NO set trapping seasons for rights-based harvest in the harvester's traditional use area (ECC). The 'AH' season rows in this dataset reproduce the GNWT Summary's Jul 1 - Jun 30 spans for Aboriginal harvesters: they record the ABSENCE of a closed season, not a territorial open season, and must be modelled and labelled that way in the clone. One exception: lynx — the Summary gives Aboriginal harvesters a set season (Nov 15 - Apr 15) in area I/LX/01 only.","season_housekeeping":"Trapping equipment must not be set before the first day of a season and must be removed or rendered harmless by the last day of the season (GNWT Summary, fur-trapper rules).","special_harvester_licence":"An SHL can be issued to a person who does not have Aboriginal harvesting rights in an area but is supporting an Indigenous family, living a subsistence lifestyle, or given permission to trap or harvest more than a Resident, Non-resident or General Hunting Licence allows. An SHL cannot be used outside the seasons, limits or conditions applicable to Aboriginal harvesters under the Big Game Hunting, Small Game Hunting and Trapping Regulations. All SHLs expire June 30 following the date of issue.","trap_check":"Live-hold restraining traps (soft-catch traps and leg snares that hold an animal alive) must be checked at least once every 72 hours (ECC). No check interval for killing traps was published in the sources read in this pass.","wastage":"It is an offence to waste the pelt of bear*, beaver*, coyote, ermine (stoat), fisher, fox, least weasel, lynx, marten, mink, muskrat*, otter, skunk, wolf or wolverine. *Bear, beaver and muskrat pelts may be discarded where the animal was harvested for meat."},"seasons_status":null,"seasons_note":null};
window.OPOSSUM_FOOT_CANADA_DATA["NU"] = {"check_interval":{"live_holding":"Live-capture traps for furbearers: inspect at least once every 72 hours and remove the animal (Harvesting Regulations R-011-2015 s. 5(3)).","killing":"No interval found for killing traps.","note":null},"tenure":"No trapline tenure - Nunavut Settlement Area regime; non-Inuit furbearer licence eligibility is gated by the local Hunters and Trappers Organisation (HTO).","trap_id_requirement":"None found - no trap owner-ID marking requirement in the sources searched (follow-up pass, Nov 17); identification runs through licence/tenure and pelt seals instead.","royalty":null,"nuisance_route":"None found - Wildlife Act s. 97 defence/emergency kills (report ASAP; valuable parts, generally the hide, surrendered to the local HTO under s. 100). Special exemptions under s. 21 are officer-led, not a commercial licence. [R2 Item 3]","harvest_reporting_and_sealing":"Fur tags (metal bands) evidence lawful harvest where a Total Allowable Harvest share applies. An export permit is required to take untanned furs out of Nunavut. [R1 s.5; NU dataset]","aihts_canada_only":{"canada_wide":"AIHTS in force in Canada since 1 June 1999 (Canada, the EU and Russia are parties; the US is not a party). FIC-certified traps mandatory per Phase 1 lists - killing traps: beaver, Canada lynx & bobcat, fisher, marten, muskrat (on land and underwater), otter, raccoon, weasels/ermine; restraining traps: beaver (cage), bobcat, Canada lynx, raccoon, wolf. Conventional steel-jawed leghold restraining traps on land are effectively banned for AIHTS species. Killing neck snares are NOT AIHTS traps and are not FIC-certified; provinces regulate snares separately. [R1 s.2a]","jurisdiction_specific":null},"aihts":{"applies":true,"certification_source":"Fur Institute of Canada certified-trap list (national list; Nunavut has no territory-specific schedule).","legal_basis":"Wildlife Act (C.S.Nu. c.W-50) s. 82(1): no person shall harvest game using a trap unless the trap is certified under the Agreement on International Humane Trapping Standards (AIHTS) by the Minister or another competent authority in Canada for that species, or is certified by the Minister (with the advice of a committee of elders) for a species to which the AIHTS does not apply. Section 82(3): live-capture traps must be checked as prescribed (Harvesting Regulations: at least once every 72 hours for furbearers). Traps must be removed or rendered inoperative when not in use / at the end of the harvest as provided in s. 82.","models_transcribed":false,"note":"Unlike Ontario, Nunavut law contains NO species-by-species certified-trap schedules. The AIHTS duty in s. 82(1) points outward to certification 'by the Minister or another competent authority in Canada' - in practice the national Fur Institute of Canada certified-traps list. No Nunavut-specific certified-model list was found in any official source in this pass, and none is transcribed here. Additional Nunavut trap law is prohibitory, not schedular: Harvesting Regulations R-011-2015 s. 5 bans jaw-type leghold traps on land for beaver, otter, marten, fisher, muskrat and badger, and bans conventional steel-jawed leghold traps on land for coyote, wolf, bobcat, lynx and raccoon; s. 7 bans toothed or serrated jaws, spring-pole foothold sets, and unfit or unanchored traps.","no_species_schedules":true,"source_updated":"2026-07-22 (national FIC list, as verified in the Ontario pass; not re-verified for Nunavut in this pass)","source_url":"https://fur.ca/wp-content/uploads/2026/07/CertifiedTrapsList_FIC_July-22-2026-_EN.pdf","trap_rules":["AIHTS-certified traps required for harvesting game with a trap (Wildlife Act s. 82(1)); for species the AIHTS does not cover, traps may be certified by the Minister with elders-committee advice.","Live-capture traps used for furbearers must be inspected at least once every 72 hours (Harvesting Regulations R-011-2015, under Wildlife Act s. 82(3)).","Jaw-type leghold traps are prohibited on land for beaver, otter, marten, fisher, muskrat and badger (Harvesting Regulations s. 5).","Conventional steel-jawed leghold traps are prohibited on land for coyote, wolf, bobcat, lynx and raccoon (Harvesting Regulations s. 5).","Traps with toothed or serrated jaws, spring-pole foothold sets, and traps that are unfit or not properly anchored are prohibited (Harvesting Regulations s. 7).","Wildlife taken illegally as bycatch must be delivered to a conservation officer for certification and disposal (Harvesting Regulations s. 13 and related sections).","No trapping in prescribed wildlife sanctuaries (Harvesting Regulations s. 19: Bowman Bay, James Bay Special Management Area, Thelon, Twin Islands) - Inuit exercising Agreement rights are exempt from the sanctuary prohibition as provided in the regulation."]},"license_summary":{"ages":"Per the 2026-27 Hunting Guide: a person 12+ may be issued a licence to hunt small game; 16+ for big game; ages 12-16 may be licensed for big game if endorsed by a parent or guardian.","export_permit":"An export permit is required to export wildlife or parts from Nunavut unless an exemption applies (Wildlife Act and Prescribed Matters Regulations); the export permit itself carries no fee (Fees Regulations R-010-2015 s. 1(3)(d)). GN export guidance ('Leaving Nunavut with animal products? You may need a permit') lists untanned furs among the items to check with a Wildlife Office before export.","fees":"Fees Regulations R-010-2015: harvesting licence fee $10 for all classes, plus surcharge (resident $5 / non-resident $20 / non-resident foreigner $50) = totals $15 / $30 / $60. Species authorization tag totals (fee + surcharge, Schedules E-G): wolf $15 / $140 / $170; wolverine $15 / $140 / $170; fox $15 / $30 / $70; hare and any other furbearer $10 / $20 / $40. Fur tags: no fee. Export permits: no fee. Licence/tag replacement: $10. Fees payable by an Inuk are the same as for a resident (s. 2(2)) - but see inuit_rights: an Inuk exercising s. 10 rights needs no licence at all.","fur_tags":"A person who harvests a furbearer for which a TAH is established must attach a fur tag to the hide or pelt (non-reusable attachment, as soon as practicable, may wait until after fleshing). Without the fur tag attached, no person shall export the pelt or hide from Nunavut or traffic in it (Licences and Tags Regulations s. 43). Fur tags expire at the end of June if not attached.","guides":"Non-residents and non-resident foreigners may hunt big game only through a licensed outfitter accompanied by a professional big game guide; the community HTO approves guides and may waive the guide requirement (2026-27 Hunting Guide).","harvest_report":"Reporting Regulations R-014-2015 s. 15: a person who harvests a species for which a TAH is established must submit a harvest report (contact information, hunting licence number or enrolment number, tag numbers if any, date and location of harvest, and further prescribed particulars) to a conservation officer. Dealers, tanners and taxidermists keep records of wildlife received and file monthly reports within 10 days after month end, even for nil months (s. 7).","harvesting_licence":"A harvesting licence is required for anyone without a s. 10/12/13/14/16 right (Wildlife Act s. 18). Small game requires a harvesting licence; big game requires a harvesting licence plus species authorization tag(s). Licences and tags are valid July 1 to June 30 and are not transferable (Guide; Wildlife Act s. 34). There is NO separate trapping licence in Nunavut.","hto_approval":"Furbearer harvest by licence is HTO-gated: Wildlife Act s. 24 restricts furbearer licences in the Nunavut Settlement Area to 1981 General Hunting Licence holders who actually harvested furbearers, or persons approved and recommended by the local HTO; s. 30(4) makes the licence subject to HTO-imposed terms and conditions. The 2026-27 Guide states the operational rule: arctic foxes, hares and ground squirrels are classed as furbearers and can only be hunted by HTO-approved individuals, and the same applies to big-game furbearers (bears, wolves, wolverines); a Conservation Officer issues the licence only on evidence of HTO approval.","inuit_rights":"Wildlife Act s. 10: an Inuk with proper identification may harvest wildlife with NO licence, tax or fee, throughout Nunavut, up to the adjusted basic needs level (TAH established) or the full level of economic, social and cultural needs (no TAH). Sections 12-14 extend no-licence harvest rights to Inuit of Northern Quebec, NWT Aboriginal people, and Manitoba/Saskatchewan band members in traditional areas; s. 16 covers assignees. Licences and Tags Regulations confirm no licence is required of a person with a s. 10/12/13/14/16 right. The Nunavut Agreement prevails over the Act in case of conflict (Act s. 5(2)).","report_violation":"Report hunting violations to the nearest GN Wildlife Office (2026-27 Guide, 'Reporting Hunting Violations'). Department of Environment headquarters: 867-975-7700, environment@gov.nu.ca.","residency":"Three licensed-hunter classes (Guide; Wildlife Act s. 4): Resident - Canadian citizen or landed immigrant living in Nunavut at least 3 months; Non-resident - Canadian citizen or landed immigrant living outside Nunavut or resident less than 3 months; Non-resident foreigner - neither a resident nor a Canadian citizen.","species_authorization_tags":"No person who requires a licence shall harvest furbearers (or big game other than white-tailed deer) without a species authorization tag (Licences and Tags Regulations s. 40). The tag is affixed to the licence; on harvest the holder cancels it by notching the licence page to show the date (s. 42). Tags expire at the end of June. Per the Guide, the tag must be attached to the harvested animal as soon as possible, but for wolf and wolverine (and bears) attachment to the raw pelt or hide may wait until immediately after fleshing.","trap_check":"Live-capture traps used to harvest furbearers must be inspected at least once every 72 hours (Harvesting Regulations R-011-2015, under Wildlife Act s. 82(3))."},"seasons_status":"no_published_trapping_seasons","seasons_note":"Nunavut has NO published trapping seasons: the Harvesting Regulations (R-011-2015) contain no season dates at all - they regulate methods, trap prohibitions, bycatch, Total Allowable Harvest accounting and sanctuaries. Inuit harvest is rights-based (Wildlife Act s. 10 - no licence, no season in law); non-Inuit furbearer licences require local HTO approval. The source dataset's species rows were derived from the 2026-27 Hunting Guide and are WITHHELD from this pack so no hunting table is presented as a trapping season. Decision pending (Tanner): ship a partial dataset with honest labels, or defer Nunavut."};
window.OPOSSUM_FOOT_CANADA_DATA["ON"] = {"check_interval":{"live_holding":"Daily - every live-holding trap south of the most northerly east-west CN Rail line (O. Reg. 667/98 s. 25(3)); relaxing cable restraints daily everywhere.","killing":"No general check interval stated in the sources.","note":null},"tenure":"Registered trapline areas on Crown land (allocated by the Ministry as vacancies occur) plus private-land (landowner) licences; licence is area-specific and carries licence-specific quotas.","trap_id_requirement":"None found - no trap owner-ID marking requirement in the sources searched (follow-up pass, Nov 17); identification runs through licence/tenure and pelt seals instead. Near-miss: containers used to transport pelts must be marked with contents and consignor/consignee name and address - shipment marking, not trap marking.","royalty":"Royalty on pelts transported out of Ontario: 5.5% of the average Ontario auction price, payable before transport (O. Reg. 666/98 s. 32); an export licence is also required. [R2 Item 5; R1 s.5]","nuisance_route":"Paid route exists - FWCA s. 31 protection of property: an owner may harass, capture or kill damaging wildlife on their own land and may use an agent. Prescribed agent classes (O. Reg. 665/98 s. 132) include licensed trappers and persons whose business is primarily removing nuisance wildlife - but business-class agents may only harass or capture-and-release, NOT kill. Live-captured animals not killed must be released within 24 hours, within ~1 km of capture. Others act under a Minister's Term Agent Authorization (ongoing) or Individual Agent Authorization (one-off). [R1 s.4]","harvest_reporting_and_sealing":"Mandatory Season-End Harvest Report: record harvest within 24 hours of season close; submit by June 10 with numbers harvested, sold/shipped and remaining in possession, to OFMF or the applicable Provincial Treaty Organization. Failure is an offence. [R1 s.5]","aihts_canada_only":{"canada_wide":"AIHTS in force in Canada since 1 June 1999 (Canada, the EU and Russia are parties; the US is not a party). FIC-certified traps mandatory per Phase 1 lists - killing traps: beaver, Canada lynx & bobcat, fisher, marten, muskrat (on land and underwater), otter, raccoon, weasels/ermine; restraining traps: beaver (cage), bobcat, Canada lynx, raccoon, wolf. Conventional steel-jawed leghold restraining traps on land are effectively banned for AIHTS species. Killing neck snares are NOT AIHTS traps and are not FIC-certified; provinces regulate snares separately. [R1 s.2a]","jurisdiction_specific":"Exclusive use of certified restraining traps for raccoon is mandatory in Ontario (FIC list Note 1 provinces: ON, QC, PEI, NB, NS). Ontario implements AIHTS through O. Reg. 667/98 ss. 18-18.1 and Schedules 1 (certified killing) and 2 (certified restraining). [R1 s.2a]"},"aihts":{"certified_killing_traps_schedule_1":[{"models_approx":25,"note":"Killing traps only; restraining (cage/live) traps are in Schedule 2.","species":"Beaver"},{"models_approx":19,"note":"","species":"Bobcat"},{"models_approx":19,"note":"","species":"Canada lynx"},{"models_approx":13,"note":"","species":"Fisher"},{"models_approx":15,"note":"","species":"American marten"},{"models_approx":38,"note":"Includes 'any jaw-type killing trap'.","species":"Muskrat"},{"models_approx":16,"note":"","species":"River otter"},{"models_approx":31,"note":"","species":"Raccoon"},{"models_approx":26,"note":"Covers least, long-tailed and short-tailed weasel.","species":"Weasel"}],"certified_restraining_traps_schedule_2":[{"models_approx":7,"note":"Cage/live traps.","species":"Beaver"},{"models_approx":6,"note":"","species":"Bobcat"},{"models_approx":4,"note":"","species":"Canada lynx"},{"models_approx":1,"note":"'Any jaw type leg-hold trap'.","species":"Muskrat"},{"models_approx":5,"note":"","species":"Raccoon"},{"models_approx":14,"note":"","species":"Gray wolf"}],"models_note":"This pass captured schedule structure and approximate model counts per species, not the full model-by-model list. Full transcription of Schedules 1 and 2 is a defined follow-on task (see the scoping report). Certification is not the same as current manufacturing: several certified models are legacy/discontinued. Do not present the certified list as a shopping list without a retailer-availability check.","models_transcribed":false,"no_certified_trap_required":["Mink","Virginia opossum","Striped skunk","Red fox","Coyote","Red squirrel","Arctic fox","Black bear"],"note":"Ontario implements AIHTS through O. Reg. 667/98 ss. 18-18.1 and Schedules 1 (certified killing traps) and 2 (certified restraining traps). A 'certified trap' is a killing trap listed in Schedule 1 column 3 or a restraining trap listed in Schedule 2 column 3 for that species (s. 1(1)). The Fur Institute of Canada maintains the national certified-trap list (updated July 22, 2026); Ontario's schedules are drawn from it. AIHTS was agreed in 1997 and ratified by Canada in June 1999; it covers 12 North American species. Phase 1 regulated species match Ontario's schedules; Phase 2 species are not yet regulated.","ontario_schedules_url":"https://www.ontario.ca/laws/regulation/980667","source_updated":"2026-07-22","source_url":"https://fur.ca/wp-content/uploads/2026/07/CertifiedTrapsList_FIC_July-22-2026-_EN.pdf","trap_rules":["Only certified traps may be used for species listed in Schedules 1 and 2 (O. Reg. 667/98 s. 18).","Body-gripping traps with jaw spread over 22 cm are banned in WMUs 60-95 except in-water beaver/otter sets (s. 18.1(2)).","Leg-hold traps may only be used as permitted by s. 19: coyote and fox within size limits; beaver, muskrat, otter and mink in submersion sets; red squirrel in enclosed killing sets; certified leg-holds for raccoon, lynx and bobcat.","No leg-hold traps for fisher, marten, opossum, skunk or weasel.","Leg-hold jaw spread: max 18 cm on land, 21 cm in water; 23 cm for wolf with a certified trap (s. 24).","Trap chain max 31 cm (s. 25(1)); live-holding traps inspected at least once daily (s. 25(3)), except north of the CNR line (s. 25(4)).","Black bear: foot snares, box or culvert traps only (s. 20); no trapping within 400 m of a waste disposal site (s. 22).","Night dispatch of trapped animals: rim-fire firearm only (s. 27.1)."]},"license_summary":{"certified_traps":"Only AIHTS-certified traps may be used for species listed in Schedule 1 (killing traps) and Schedule 2 (restraining traps) of O. Reg. 667/98 (s. 18). See the 'aihts' section of this dataset.","course":"Fur Harvest, Fur Management and Conservation Course (40 hours: 32 classroom + 8 hands-on) completed within the last 5 years; required for a first trapping licence (O. Reg. 667/98 s. 11).","fees":"Trapping licence $39.55; secondary (helper/youth) $16.95 (HST included). Outdoors Card $8.57 + HST.","harvest_report":"Mandatory Season-End Harvest Report: record the quantity of each species harvested within 24 hours of the close of the season for that species; submit by June 10 to the Ontario Fur Managers Federation or the applicable Provincial Treaty Organization (s. 13).","hunting_furbearers":"Arctic fox, raccoon, opossum, red fox, skunk and weasel may also be hunted under a Small Game Licence (Hunting Summary pp. 88-89). Wolf and coyote may be hunted under a Small Game Licence plus a Wolf/Coyote Tag in WMUs where a tag is required (max 2 tags per calendar year). A CITES export permit is required to export wolves from Canada. Furbearing mammals generally may not be hunted in provincial parks or Crown Game Preserves.","licence_types":"Landowner, resident, head trapper (Registered Trapline Area), helper trapper, youth. Only one registered trapline area per licence (s. 9).","licensing_transition":"The Fish and Wildlife Licensing Service (huntandfishontario.com) is being replaced by FishHuntON, launching December 10, 2026; the current system is unavailable December 7-9, 2026 (ontario.ca, October 30, 2026). Licence URLs in this dataset may go stale within a month of the retrieval date.","otter_incidental":"An otter taken out of season may only be possessed if it was incidentally killed while lawfully trapping beaver despite all due diligence, and the incident is recorded on the season-end harvest report (Trapping Regulations Summary, Pelt possession).","permission":"Trap only on land designated on the licence; written landowner permission required on private land (s. 8).","quotas":"Harvest quotas are fixed on the licence and are licence-specific (s. 6). Trapping less than 75% of the beaver quota fixed by the licence is an offence and can mean the licence is not renewed (s. 7). There are no bag limits in Table 6; harvest is governed by licence quotas.","report_violation":"MNR TIPS line 1-877-847-7667 (1-877-TIPS-MNR); anonymous via Crime Stoppers 1-800-222-TIPS (8477). Natural Resources Information and Support Centre: 1-800-387-7011.","trap_check":"Every live-holding trap must be inspected at least once a day (s. 25(3)), except in the parts of Ontario north of the most northerly east-west CNR line / Calstock-Nakina forest access road (s. 25(4)).","trapping_licence":"A trapping licence is required (O. Reg. 667/98). Adult: 16+, Ontario resident or Canadian citizen, valid Outdoors Card, hunter accreditation on file, and the Fur Harvest, Fur Management and Conservation Course completed within the last 5 years (40 hours: 32 classroom + 8 hands-on). Youth 12-15: course + parental consent, under direct supervision of a licensed trapper 18+. Trapping licences are paper applications to the MNR work centre; payment to the Ontario Fur Managers Federation or the applicable Provincial Treaty Organization.","wolf_coyote_reporting":"A wolf or coyote killed in WMUs 1-10, 11A, 11B, 12-42, 46-50 or 53-58 in protection of property must be reported immediately to a ministry office unless a Notice of Possession is submitted. Wolf/coyote tag holders must submit a mandatory hunter report (deadline January 14, 2027 for the 2026 season)."},"seasons_status":null,"seasons_note":null};
window.OPOSSUM_FOOT_CANADA_DATA["PE"] = {"check_interval":{"live_holding":"Live-holding traps: daily. All trapping devices: at least once every 72 hours (Fur Harvesting Regulations s. 9(1)(h)-(i)).","killing":"Every 72 hours generally; snares designed to kill red fox/coyote: every 48 hours.","note":"Verified in regulation text (R2 Item 2); supersedes R1's unverified secondary summary of 'every 2-3 days'."},"tenure":"No tenure system - small, private-land-dominated province; landowner permission required before setting any traps.","trap_id_requirement":"REQUIRED - every trap and snare must be clearly identified with the trapper's permanent trapper registration number (Fur Harvesting Regulations s. 2(4)-(5)); possessing unmarked snares in wildlife habitat is also barred (s. 4(4)). Verified in regulation text. [R2 Item 6]","royalty":null,"nuisance_route":"Department-issued nuisance permits to designated trappers (a nuisance beaver permit removing roughly 140-200 beavers a year; a nuisance coyote permit, 5 or fewer a year since 2020). Relocating problem beavers is not accepted - removal is lethal. No standing paid-operator licence; whether permit trappers are paid is not stated in the sources. [R2 Item 3]","harvest_reporting_and_sealing":"NONE - no mandatory trapper harvest report and no pelt sealing requirement in the Fur Harvesting Regulations (verified in regulation text). Instead: possession of a green hide/carcass from 5 days after season close to the next open season is prohibited without a Minister's permit (s. 10); fur dealers (not trappers) must report purchases monthly (s. 13); harvest data comes from a voluntary phone survey. [R2 Item 2]","aihts_canada_only":{"canada_wide":"AIHTS in force in Canada since 1 June 1999 (Canada, the EU and Russia are parties; the US is not a party). FIC-certified traps mandatory per Phase 1 lists - killing traps: beaver, Canada lynx & bobcat, fisher, marten, muskrat (on land and underwater), otter, raccoon, weasels/ermine; restraining traps: beaver (cage), bobcat, Canada lynx, raccoon, wolf. Conventional steel-jawed leghold restraining traps on land are effectively banned for AIHTS species. Killing neck snares are NOT AIHTS traps and are not FIC-certified; provinces regulate snares separately. [R1 s.2a]","jurisdiction_specific":"Prince Edward Island is a FIC Note 1 province (exclusive use of certified restraining traps for raccoon). [R1 s.2a]"},"aihts":{"certified_killing_traps_schedule_c":[{"models_approx":22,"models_transcribed":true,"note":"Approved for use underwater and on land. Transcribed from Schedule C of the Fur Harvesting Regulations (office consolidation current to September 12, 2015): B.M.I. BT 300; Bélisle Classic 330; Bélisle Super X 280; Bélisle Super X 330; B.M.I. 280 Body Gripper; B.M.I. 330 Body Gripper; Bridger 330; Duke 330; LDL C280; LDL C280 Magnum; LDL C330; LDL C330 Magnum; Rudy 280; Rudy 330; Sauvageau 1000-11F; Sauvageau 2001-8; Sauvageau 2001-11; Sauvageau 2001-12; Species-Specific 330 Dislocator Half Magnum; Species-Specific 440 Dislocator Half Magnum; Woodstream Oneida Victor Conibear 280; Woodstream Oneida Victor Conibear 330.","species":"Beaver"},{"models_approx":28,"models_transcribed":true,"note":"Approved for use on land. Transcribed from Schedule C (2015 consolidation): Bélisle Classic 220; Bélisle Super X 160; Bélisle Super X 220; Bélisle Super X 280; B.M.I. 160 Body Gripper; B.M.I. 220 Body Gripper; B.M.I. 280 Body Gripper; B.M.I 280 Magnum Body Gripper; Bridger 160; Bridger 220; Duke 160; Duke 220; Koro #2; LDL C 160; LDL C 220; LDL C 220 Magnum; LDL C 280 Magnum; Northwoods 155; Rudy 160; Rudy 160 Plus; Rudy 220; Rudy 220 Plus; Sauvageau 2001-6; Sauvageau 2001-7; Sauvageau 2001-8; Species-Specific 220 Dislocator Half Magnum; Woodstream Oneida Victor Conibear 160; Woodstream Oneida Victor Conibear 220.","species":"Raccoon"},{"models_approx":20,"models_transcribed":true,"note":"Approved for use on land. Transcribed from Schedule C (2015 consolidation): Bélisle Super X 110; Bélisle Super X 120; B.M.I. Body Gripper 120; B.M.I. Body Gripper 120 Magnum; B.M.I. 126 Magnum; Bridger 120; Duke 120; Koro Muskrat; LDL B120 Magnum; Ouell 4-11-180; Ouell RM; Rudy 110; Rudy 120; Rudy 120 Magnum; Sauvageau 2001-5; Sauvageau C120 Magnum; Sauvageau C120 'Reverse Bend'; Triple M; Woodstream Oneida Victor Conibear 110; Woodstream Oneida Victor Conibear 120.","species":"Muskrat"},{"models_approx":20,"models_transcribed":true,"note":"Approved for use on land. Transcribed from Schedule C (2015 consolidation): Bélisle Super X 110; Bélisle Super X 120; B.M.I. #60; B.M.I. 120 Body Gripper Magnum; B.M.I. 126 Body Gripper Magnum; Bridger 120; Koro Muskrat Trap; Koro Rodent Trap; LDL B120 Magnum; Ouell 411-180; Quell 3-10; Ouell RM; Rudy 120 Magnum; Sauvageau C120 Magnum; Sauvageau C120 'Reverse Bend'; Sauvageau 2001-5; Triple M; Victor Rat Trap; Woodstream Oneida Victor Conibear 110; Woodstream Oneida Victor Conibear 120.","species":"Weasel"}],"certified_restraining_traps":[],"models_note":"Unlike Ontario, PEI's Schedule C model lists are short enough to transcribe in full, and they are transcribed above from the 2015 office consolidation of the Fur Harvesting Regulations. The current Schedule C may have been amended since 2015 (the schedule's amendment trail ends at EC539/15 in the consolidation read); re-verify against the current consolidation before launch. Certification is not the same as current manufacturing: several listed models are legacy/discontinued. Do not present the list as a shopping list without a retailer-availability check (not done in this pass).","models_transcribed":true,"no_certified_trap_required":["Mink","Red fox","Coyote","Striped skunk","Red squirrel"],"note":"PEI implements AIHTS through its own Schedule C of the Fur Harvesting Regulations (EC663/04): 'List of Approved Body-Gripping Traps (Certified under the Canadian Trap Certification Program and Approved for use as Killing Traps for Beaver, Muskrat, Raccoon and Weasel in Prince Edward Island)'. CONFIRMED: PEI adopts the Fur Institute of Canada / Canadian Trap Certification Program certified list, but only as filtered through Schedule C - a trap certified nationally is NOT legal for these species in PEI unless it appears in Schedule C. The requirement covers body-gripping (killing) traps only: on land for beaver, raccoon, muskrat and weasel (s. 5(6)), and underwater for beaver and muskrat (s. 5(7)). PEI has NO certified restraining-trap schedule; restraining traps are governed by design standards instead (modified foot-hold traps for coyote/fox, padded or foot-encapsulating traps for raccoon, drowning sets for beaver/mink/muskrat). Snares are not AIHTS-certified devices; since September 2025 PEI requires killing neck snare designs or live-restraining snares and prohibits snares on public land (announced changes; amended text not read in this pass). AIHTS was agreed in 1997 and ratified by Canada in June 1999; the FIC maintains the national certified-trap list (updated July 22, 2026).","pei_schedule_url":"https://www.princeedwardisland.ca/en/legislation/wildlife-conservation-act/fur-harvesting-regulations","source_updated":"2026-07-22","source_url":"https://fur.ca/wp-content/uploads/2026/07/CertifiedTrapsList_FIC_July-22-2026-_EN.pdf","trap_rules":["Body-gripping traps used to take beaver, raccoon, muskrat or weasel on land must be approved traps listed in Schedule C (Fur Harvesting Regulations s. 5(6)); the same applies underwater for beaver and muskrat, except a muskrat set that prevents resurfacing (s. 5(7)).","Body-gripping traps with jaw spread greater than 16 cm may be set only in or over water, in a dog-proof enclosure meeting the standards in s. 5(3)-(4), or at least 1.5 m off the ground (s. 5(2)).","Foot-hold traps: for beaver, mink or muskrat they must be attached to a drowning device (s. 6(1)(a)-(b)); for raccoon, jaws must be rubber-padded or the trap foot-encapsulating (s. 6(1)(d)); for coyote or red fox, jaws must be laminated, off-set, padded, or similarly modified (s. 6(1)(e) - the 'modified foot-hold trap'). No running pole or spring pole sets with foot-hold traps (s. 6(3)).","Permitted devices in wildlife habitat during open season are limited to: box traps; body-gripping traps designed to kill quickly; submarine traps; non-powered snares; steel-jawed traps with jaw spread under 19 cm; and foot-encapsulating traps (s. 8(2)). Toothed traps, deadfalls and hooks are prohibited (s. 7).","Snares (pre-September-2025 text): wire no larger than single strand brass wire of 20 gauge except during the fox/coyote snaring season (s. 4(1)); heavier snares need a self-locking device (s. 4(2)); no snare for coyote or red fox within 50 m of a bait unless the bait is concealed from the air or in an open field (s. 4(5)); no fox/coyote snare in a highway right-of-way (s. 4(6)); no snare within 200 m of an occupied dwelling without the occupier's permission, or a baited snare within 300 m (s. 9(1)(k)-(l)); fox/coyote snare wire minimum 1.98 mm (s. 9(1)(m)). September 2025 changes prohibit snares on public land and bait used with snares and restrict snares to killing neck snare or live-restraining designs (news release; amended text not read).","Trap-check intervals (s. 9(1)(h)-(i)): every trapping device must be examined at least once every 72 hours; traps designed to hold an animal alive must be examined at least once a day; snares designed to kill red fox or coyote must be examined at least once every 48 hours.","Every trap or snare must be clearly identified with the trapper's permanent trapper registration number (s. 2(4)-(5)). Metal dies are no longer required (2020 Hunting and Trapping Summary) but the ID marking requirement stands.","No trap may be placed in wildlife habitat before the first day of the open season for that species or left after its close (s. 8(1)). In February and March, beaver, muskrat and mink traps may be set only in or over water (s. 9(1)(d)); in March, weasel traps must be Victor rat traps (s. 9(1)(e)).","Trapping is restricted or closed on listed public lands (about 3,525 hectares closed province-wide, including demonstration woodlots, natural areas and trail properties named on the Trapping Information Centre page). Since September 2025, landowners may remove traps set on their property without permission, and permission standards for traps and snares on private land were tightened (news release)."]},"license_summary":{"certified_traps":"Body-gripping traps for beaver, raccoon, muskrat and weasel (on land) and beaver/muskrat (underwater) must be approved traps listed in Schedule C of the Fur Harvesting Regulations - PEI's adoption of the Canadian Trap Certification Program (FIC) list. See the 'aihts' section of this dataset.","course":"Trapper Education Course (approved trapper education program) required for a first trapping licence: Fur Harvesting Regulations s. 2(1)(a)(ii) (age 16+) and s. 2(2) (junior). Courses are held twice a year, usually April and October; free for ages 12-15, $20 for ages 16+ (Trapping Information Centre). Since September 2025, certified trappers must also complete continuing education to maintain eligibility, fully phased in by 2029 (Government of PEI news release, September 16, 2025).","fees":"Trapping licence $10.00 (18+) and junior trapping licence $5.00 (Schedule B, Fur Harvesting Regulations, as amended by EC305/13; HST not included) - no newer official fee source was found in this pass, so treat as to-confirm. Wildlife Conservation Fund (WCF) licence: $20/year, $13/year for ages 65+, no fee under 16 (Trapping Information Centre; WCF page). Fur-bearer hunting licence $5 (resident, all age classes; no fee for Canadian Armed Forces members/veterans); non-resident hunting licence $75 seasonal / $60 three-day (Buy a Hunting Licence Online service page). Snowshoe hare snaring licence $5. Trapper Education Course $20 (16+), free 12-15.","harvest_report":"Fur dealers must keep records and report monthly during open season and within 30 days of a season close (Fur Harvesting Regulations s. 13). A trapper must, on request by a conservation officer, provide information on the trapping of any fur-bearing animal whose green hide or carcass they possess (s. 10(2)). The annual summaries include a Trapper Harvest Log; whether returning a trapper harvest report is mandatory was NOT verified in this pass - see verification.known_gaps. There is no pelt tagging or sealing requirement in the Fur Harvesting Regulations.","hunting_furbearers":"Raccoon, red fox, coyote and red squirrel may be hunted under a fur-bearer hunting licence ($5 resident). Beaver, mink, muskrat, skunk and weasel may be taken ONLY by trapping (Fur Harvesting Regulations s. 9(1)(f)). A fur-bearer hunting licence holder may sell the pelts of raccoon, coyote, red fox or red squirrel to a licensed fur dealer (s. 12(3)). Snowshoe hare hunting (Oct 1 - Mar 31, daily limit 5) is under the general hunting licence; hare snaring (Nov 1 - Feb 28) needs its own $5 Snowshoe Hare Snaring Licence.","licence_types":"Trapping licence; junior trapping licence; fur-bearer hunting licence; general hunting licence; snowshoe hare snaring licence; fur dealer's licence; fur export permit. A trapping licence expires on March 31 following the date of issue (Fur Harvesting Regulations s. 2(8)). Trapping licences are sold in person at Access PEI offices and the Forests, Fish and Wildlife office, 183 Upton Road, Charlottetown (Trapping Information Centre); hunting licences are also sold online.","permission":"Landowner permission is required before setting traps (Trapping Information Centre; Fur Harvesting Regulations framework). September 2025 changes added permission requirements for traps on private land, a higher permission standard for snares, and a landowner right to remove traps set without permission (news release). Snares have been prohibited on public land since the September 2025 changes, and trapping is restricted/closed on about 3,525 hectares of listed public land.","quotas":"PEI has NO licence quotas and NO bag limits for trapping: Schedule II of the Hunting and Trapping Seasons Regulations sets open seasons with no daily, season, or possession limits for any trapped species. The only bag limit in this dataset is snowshoe hare hunting (5/day).","report_violation":"Report a violation to a Conservation Officer: leave a detailed message anytime at 902-368-4884 (Government of PEI, 'Report a Violation to a Conservation Officer', updated February 2, 2026). Forests, Fish and Wildlife Division: 902-368-4683 / 1-866-368-4683.","trap_check":"Every trapping device must be examined at least once every 72 hours; traps designed to hold an animal alive at least once a day; snares designed to kill red fox or coyote at least once every 48 hours (Fur Harvesting Regulations s. 9(1)(h)-(i), 2015 consolidation - confirm against the current consolidation, see verification.known_gaps).","trapping_licence":"A trapping licence is required to trap fur-bearing animals (Fur Harvesting Regulations s. 2). Eligibility: held a valid trapping licence within the previous 5 years, OR age 16+ and successful completion of an approved trapper education program; junior licence for under-16s who have completed the program. Each licensed trapper is assigned a permanent trapper registration number, and every trap or snare set must be clearly identified with it (s. 2(4)-(5)). A current Wildlife Conservation Fund licence is also required."},"seasons_status":null,"seasons_note":null};
window.OPOSSUM_FOOT_CANADA_DATA["QC"] = {"check_interval":{"live_holding":"No legally required maximum check interval found - the Regulation respecting trapping and the fur trade (C-61.1, r. 21) was read in full (ss. 1-19.3) and contains no visit/check provision; ministry material says only 'visit regularly'.","killing":"Same - no interval in the regulation (r. 21 and r. 3 read in full).","note":"Confidence: not found after searching named sources (R2 Item 1). App should show 'no statutory check interval - visit regularly', not a number."},"tenure":"Leases granting exclusive trapping rights on designated territories (conditional on an annual minimum harvest), plus open trapping by management unit (UGAF).","trap_id_requirement":"None found - no trap owner-ID marking requirement in the sources searched (follow-up pass, Nov 17); identification runs through licence/tenure and pelt seals instead.","royalty":"5% of the Quebec average value per species (Bulletin Fourrure Quebec), owed by licensed fur traders for each raw pelt bought or obtained from a hunter or trapper (Regulation respecting fees relating to wildlife, C-61.1 r. 32, s. 13); traders keep a royalty register and remit monthly. Verified in regulation text. [R2 Item 5]","nuisance_route":"No NWCO-style licence found. C-61.1 s. 67: a person, or anyone lending him assistance, may capture, move or kill an animal attacking him or damaging his property if it cannot be frightened off (duties under s. 68: release unharmed live animals, declare wounded/dead animals). Whether PAID assistance under s. 67 is expressly sanctioned is not stated in the sources - unconfirmed. SEG permits (scientific/educational/management) are the ministerial authorization route. [R2 Item 3]","harvest_reporting_and_sealing":"Black bear must be registered within 15 days of leaving the trapping ground, with a transportation coupon attached before the animal is moved; sale of a raw bear pelt requires proof of registration. Polar bear export needs registration proof plus tag number. [R1 s.5]","aihts_canada_only":{"canada_wide":"AIHTS in force in Canada since 1 June 1999 (Canada, the EU and Russia are parties; the US is not a party). FIC-certified traps mandatory per Phase 1 lists - killing traps: beaver, Canada lynx & bobcat, fisher, marten, muskrat (on land and underwater), otter, raccoon, weasels/ermine; restraining traps: beaver (cage), bobcat, Canada lynx, raccoon, wolf. Conventional steel-jawed leghold restraining traps on land are effectively banned for AIHTS species. Killing neck snares are NOT AIHTS traps and are not FIC-certified; provinces regulate snares separately. [R1 s.2a]","jurisdiction_specific":"AIHTS traps now required for live capture of raccoon in cages/boxes; certified coyote live-capture (restraining) traps mandatory as of the 2028-2029 trapping periods. Quebec is also a FIC Note 1 province for raccoon restraining traps. [R1 s.2a]"},"aihts":{"certification_source":"Ministere de l'Environnement, de la Lutte contre les changements climatiques, de la Faune et des Parcs (MELCCFP) - 'Listes des pieges certifies' published on the ministry website (referenced in Note 2 to Schedule II of C-61.1, r. 21); the underlying national list is the Fur Institute of Canada certified-trap list (updated July 22, 2026).","certified_combinations_note2":[{"species":"Long-tailed weasel","types":["1"]},{"species":"Least weasel","types":["1"]},{"species":"Beaver","types":["1","9"]},{"species":"Ermine","types":["1"]},{"species":"River otter","types":["1"]},{"species":"Canada lynx","types":["1","3","5"]},{"species":"Bobcat","types":["1","3","5"]},{"species":"American marten","types":["1"]},{"species":"Fisher","types":["1"]},{"species":"Muskrat","types":["1","4"]},{"species":"Raccoon","types":["1","3"]},{"species":"Wolf","types":["5","8"]}],"models_note":"This pass captured the certification STRUCTURE (which implement types must be certified for which species, per Note 2 to Schedule II), not the model-by-model certified trap list. Certification is not the same as current manufacturing: several certified models are legacy/discontinued. Do not present the certified list as a shopping list without a retailer-availability check.","models_transcribed":false,"no_certified_trap_required":["Coyote (killing sets; certified traps required for LIVE capture from the 2028-2029 period, per the ministry's three-year notice)","Red squirrel","Gray squirrel","Striped skunk","Red fox","Arctic fox"],"note":"Quebec implements the AIHTS (Accord sur les normes internationales de piegeage sans cruaute / Agreement on International Humane Trapping Standards, D. 116-2000) differently from Ontario: instead of a schedule of certified trap MODELS in the regulation, Schedule I of C-61.1, r. 21 defines nine implement TYPES, Schedule II assigns permitted types to each species, and Note 2 to Schedule II requires specified type/species combinations to be certified as conforming to the AIHTS. The operative certified-model lists are published by the ministry ('Listes des pieges certifies'). Three-year notice (quebec.ca, March 31, 2026): certified traps will be required for the live capture of raccoon from the 2027-2028 trapping period and of coyote from the 2028-2029 period.","source_updated":"2026-07-22","source_url":"https://fur.ca/wp-content/uploads/2026/07/CertifiedTrapsList_FIC_July-22-2026-_EN.pdf","trap_rules":["Only the implement types listed in Schedule II for a species may be used for that species (C-61.1, r. 21, s. 12(3)). Schedule I defines types 1-9: type 1 = quick-kill spring trap with un-toothed jaws; type 2 = locking neck snare (quick-kill); type 3 = live-holding foot-hold spring trap; type 4 = foot-hold trap or snare rigged for drowning; type 5 = foot snare (lacets) with locking device; type 6 = foot-hold trap with anti-self-mutilation device rigged for drowning; type 7 = underwater cage (cage sous-marine); type 8 = live-holding foot-hold trap with padded/offset/laminated jaws (min 9 mm); type 9 = live-capture cage or box (max 122 cm x 46 cm).","Type 1 implements for long-tailed weasel, least weasel, beaver, ermine, river otter, Canada lynx, bobcat, American marten, fisher, muskrat and raccoon; type 3 for raccoon; type 4 for muskrat; types 3 and 5 for Canada lynx and bobcat; types 5 and 8 for wolf; and type 9 for beaver must be AIHTS-certified (Schedule II, Note 2).","Black bear: type 5 foot snare only per Schedule II, plus a type 2 snare is permitted except from May 15 to June 30 (s. 12). Food bait for black bear is prohibited July 1-August 15 (UGAFs 6, 38-40, 50, 56-66) and July 1-August 31 (UGAFs 1-5, 7-37, 41-49, 51-55, 70-86).","Type 2, 3, 5 and 8 implements must be set so the trapped animal can never be left suspended without support (s. 12).","Muskrat and American mink may also be trapped with a type 7 underwater cage from the species' opening date in each UGAF until December 31; type 7 is prohibited from January 1 to May 15 (s. 14). Inside a muskrat house only type 1 and 6 implements may be placed (Schedule II, Note 1).","A licence holder may use a firearm to dispatch a trapped black bear, lynx, wolf, fox, raccoon, coyote, beaver or striped skunk (s. 16). Trapping may be practised at night (quebec.ca, Regles generales).","NO general trap-check (visit) interval is prescribed in C-61.1, r. 21 or C-61.1, r. 3 as read in this pass - see verification.known_gaps."]},"license_summary":{"certified_traps":"AIHTS-certified implements are required for the type/species combinations in Note 2 to Schedule II of C-61.1, r. 21; the ministry publishes the certified trap lists ('Listes des pièges certifiés'). See the 'aihts' section of this dataset.","course":"Certificat du chasseur ou du piegeur with code 'P' (trapper certificate) is mandatory for a Quebec RESIDENT to obtain a professional trapping licence (C-61.1, r. 21, s. 4(2)). To earn it: be at least 12 years old, complete the training on trapping and fur-bearing animal management ('formation sur le piegeage et la gestion des animaux a fourrure') given by associations affiliated with the Federation des trappeurs gestionnaires du Quebec (FTGQ), and pass the examination. The certificate is permanent and bears code P (quebec.ca, 'Obtenir un certificat du piegeur', updated August 4, 2026).","exclusive_rights_leases":"On territories where exclusive trapping rights have been granted (territoires reserves aux seules fins de piegeage, zones d'exploitation controlee (zecs), wildlife reserves, outfitter territories), a trapper must hold a bail de droits exclusifs de piegeage (exclusive trapping rights lease) or carry the lease holder's written authorization under s. 96 of the Act (C-61.1, r. 21, s. 10.2). Leases are allocated by draw to residents 18+ holding the trapper certificate; term is 9 years, automatically renewable (C-61.1, r. 3, ss. 14-15); rent is $2.22/km2 per year (indexed; minimum $22.20) (r. 3, s. 16, amounts as indexed). A lease holder must trade at least 15 undressed pelts of at least 5 fur-bearing species from the leased territory each year (10 pelts / 3 species if the territory is 20 km2 or less) with a licensed fur dealer (r. 3, s. 17).","fees":"2026-2027 SALE PRICES (quebec.ca, 'Acheter et partager un permis de piegeage', updated August 19, 2026; taxes and the contribution to the Fondation pour la biodiversite et la faune du Quebec included): professional trapping licence - resident $37.40, non-resident $470.48; replacement licence $7.15. The underlying droits in the Reglement sur la tarification reliee a l'exploitation de la faune (C-61.1, r. 32, s. 4, indexed April 1, 2025) are resident $29.38 and non-resident $399.03. Trapper certificate droits were $2.48 under r. 32, s. 1.1 (indexed April 1, 2025); a draft amendment published in the Gazette officielle (December 24, 2025) proposed abolishing certificate droits from April 1, 2026 - enactment not confirmed in this pass (see known_gaps).","fur_trade_and_reporting":"When trading an undressed pelt of a hunted or trapped fur-bearing animal, the professional licence holder must declare the number of the UGAF the fur comes from (C-61.1, r. 21, s. 10.3). Licensed fur dealers (permis de commercant de fourrures) must keep the minister's numbered purchase register recording, for each purchase: date, number of pelts per species, and the trapper's name, address, date of birth, hunter/trapper certificate number and the UGAF (or hunting zone) of origin; register copies go to the minister by September 10 each year (r. 21, s. 19.2). No general season-end harvest report by the trapper was found in r. 21 or r. 3 - the register system is dealer-side (contrast Ontario's trapper-filed Season-End Harvest Report).","harvest_limits":"Black bear is the only species with a harvest limit (limite de prise) in the current regulation: maximum 4 per year per professional licence, apportioned by UGAF groups (C-61.1, r. 21, s. 17). The Canada lynx and bobcat limits that appeared in earlier versions of s. 17 are revoked in the current French consolidation (subparagraphs 3-7 'abrogé') - see verification.known_gaps.","indigenous_exclusivity_and_north":"Indigenous trappers hold exclusive trapping rights in UGAFs 6, 7 (except the La Verendrye wildlife reserve), 29, 31, 32, 50, 56 and 87-96 (MFFP). In northern Quebec, beaver reserves (reserves de castor, Reglement sur les reserves de castor, C-61.1, r. 28) are divided into family lots held under collective exclusive Indigenous trapping rights, and the James Bay and Northern Quebec Agreement territory (Loi sur les droits de chasse et de pêche dans les territoires de la baie James et du Nouveau-Québec, chapter D-13.1, s. 23) overlays Category I/II/III lands and registered trapping grounds (terrains de piegeage enregistres). The professional-licence/UGAF model in this dataset does not govern Indigenous harvesting under the agreements.","licence_sharing":"The professional licence may be shared: a spouse, children under 18, and students aged 18-24 may trap using the holder's licence under the conditions of C-61.1, r. 3, ss. 5-7 (under-18s must be accompanied by the holder or spouse for licence use under s. 5; residents among them must hold and carry their own code-P certificate; animals they capture count against the holder's licence and limits). The licence must be carried at all times while trapping (quebec.ca).","licence_types":"Permis de piegeage professionnel (professional trapping licence) for resident or for non-resident (C-61.1, r. 21, s. 3). A person may hold only one professional trapping licence (s. 7). The licence is valid from its date of issue to the following July 1 and includes 4 transport coupons (coupons de transport) bearing the licence number (s. 3). A Quebec resident is a person domiciled in Quebec for at least 183 days in the year preceding the activity or the certificate application (quebec.ca).","nonresident":"A non-resident licence holder may trap ONLY on their own private land, or on the territory described in the exclusive trapping rights lease of an outfitter licence holder or a professional trapping licence holder (C-61.1, r. 21, s. 10.1). Non-resident applicants must be at least 12 years old (s. 4(3)); the code-P certificate requirement in s. 4(2) applies to residents.","permission":"Trap only where authorized: on open (zone libre) public land and private land as permitted, and on exclusive-rights territories only with a lease or the lease holder's authorization document carried on the person (s. 10.2). Trapping is prohibited outright in the small territories shown in Schedules IV-XIII and XV of r. 21, and in the Beauharnois canal territory (Schedule XIV) from the third Saturday of September (September 19, 2026) to December 26.","registration_black_bear":"A trapped black bear must be identified BEFORE it is moved, using a transport coupon issued with the licence: the coupon's unique number is written indelibly on the animal or on an attached support, and the animal must stay identified until skinning (and until dressing if the pelt is destined for dressing) (C-61.1, r. 3, s. 11, as amended by D. 561-2026). The bear must then be REGISTERED (enregistrement) with the minister or an authorized registration agent, on the minister's form, within 15 days of the bear leaving the trapping site (r. 3, s. 13).","report_violation":"SOS Braconnage - Urgence faune sauvage: 1-800-463-2191 (24 hours a day, 365 days a year); email centralesos@environnement.gouv.qc.ca; online reporting form on quebec.ca. Regulation information line: 1-877-346-6763; renseignements.faune@environnement.gouv.qc.ca.","trap_check":"No general trap-check (visit) interval for professional trapping is prescribed in C-61.1, r. 21 or C-61.1, r. 3 as read in this pass (the former obligation sections of r. 3, ss. 9, 10 and 12, are revoked). This is a negative finding, not a verified absence - see verification.known_gaps.","trapping_licence":"A professional trapping licence is required to trap any fur-bearing animal in Quebec (C-61.1, r. 21, s. 3). There is no general/amateur trapping licence: Quebec trapping is a professional-licence regime. Licence purchase is through 'Mon dossier chasse et peche' or a licence sales agent (quebec.ca)."},"seasons_status":null,"seasons_note":null};
window.OPOSSUM_FOOT_CANADA_DATA["SK"] = {"check_interval":{"live_holding":"24 hours within 5 km of a town/city over 1,000 people (outside the Fur Conservation Block) and for black bear sets; 72 hours in the Southern Fur Conservation Area beyond that; 120 hours (5 days) in the Northern Fur Conservation Area (Wildlife Regulations s. 24(3)).","killing":"Same intervals - Saskatchewan does not split check intervals by trap type in s. 24(3).","note":null},"tenure":"Two macro-zones: the Northern Fur Conservation Area (fur-block membership - a fur licence can only be bought by members of an existing northern fur block) vs the Southern Fur Conservation Area (open to licensed residents, private-land/permission based). Fur licences are Saskatchewan-resident-only.","trap_id_requirement":"None found - no trap owner-ID marking requirement in the sources searched (follow-up pass, Nov 17); identification runs through licence/tenure and pelt seals instead. A HAL identification number may identify hunting baits and stands on Crown land - not traps.","royalty":"No royalty currently charged - the per-pelt royalty was removed for 2011/12 (ministerial answer tabled in the Legislative Assembly, March 28, 2011). [R2 Item 5]","nuisance_route":"Paid route exists, producer/RM-driven - under the SARM/RM Beaver Control Program, trapping a nuisance beaver requires the RM or First Nation band to contract a trapper holding a valid trapping licence; SCIC hires predation specialists where livestock predation persists. Coyotes may be shot year-round in the SFCA without a licence, but trapping them requires a fur licence plus landowner permission. [R1 s.4]","harvest_reporting_and_sealing":null,"aihts_canada_only":{"canada_wide":"AIHTS in force in Canada since 1 June 1999 (Canada, the EU and Russia are parties; the US is not a party). FIC-certified traps mandatory per Phase 1 lists - killing traps: beaver, Canada lynx & bobcat, fisher, marten, muskrat (on land and underwater), otter, raccoon, weasels/ermine; restraining traps: beaver (cage), bobcat, Canada lynx, raccoon, wolf. Conventional steel-jawed leghold restraining traps on land are effectively banned for AIHTS species. Killing neck snares are NOT AIHTS traps and are not FIC-certified; provinces regulate snares separately. [R1 s.2a]","jurisdiction_specific":null},"aihts":{"certified_killing_traps":[{"models_approx":25,"note":"","species":"Beaver"},{"models_approx":21,"note":"FIC list column is shared between bobcat and Canada lynx.","species":"Bobcat"},{"models_approx":21,"note":"FIC list column is shared between bobcat and Canada lynx.","species":"Canada lynx"},{"models_approx":13,"note":"","species":"Fisher"},{"models_approx":15,"note":"","species":"American marten"},{"models_approx":33,"note":"On land.","species":"Muskrat"},{"models_approx":null,"note":"Underwater: 'any jaw-type trap' set as a submersion set.","species":"Muskrat (underwater)"},{"models_approx":20,"note":"","species":"River otter"},{"models_approx":36,"note":"","species":"Raccoon"},{"models_approx":25,"note":"Covers ermine, least weasel and long-tailed weasel.","species":"Weasel"}],"certified_restraining_traps":[{"models_approx":6,"note":"Cage/live traps.","species":"Beaver"},{"models_approx":7,"note":"","species":"Bobcat"},{"models_approx":4,"note":"","species":"Canada lynx"},{"models_approx":5,"note":"FIC note: exclusive use of these certified raccoon restraining traps is currently mandatory only in Ontario, Quebec, Prince Edward Island, New Brunswick and Nova Scotia. Saskatchewan's own rule (s. 24(2)(i)) independently requires a certified restraining trap for any foot-hold set on land for live capture.","species":"Raccoon"},{"models_approx":14,"note":"","species":"Wolf"}],"models_note":"Counts are approximate, read from the two-page Fur Institute of Canada table (updated July 22, 2026), not hand-counted line by line. Full model-by-model transcription is a defined follow-on task (see the scoping report). Certification is not the same as current manufacturing: several certified models are legacy/discontinued. Do not present the certified list as a shopping list without a retailer-availability check.","models_transcribed":false,"no_certified_trap_required":["Badger","Black bear","Cougar","Coyote","Red fox","Arctic fox","Mink","Squirrel","Striped skunk","Wolf","Wolverine"],"note":"Saskatchewan implements AIHTS by incorporating the Fur Institute of Canada certified-trap lists by reference in the definitions: a 'certified trap' is a body-gripping trap on the FIC list of quick-kill traps certified under the Agreement on International Humane Trapping Standards, and a 'certified restraining trap' is a foot-hold trap on the FIC list of restraining traps certified under the Agreement, in each case as published and updated from time to time by the Fur Institute of Canada (The Wildlife Regulations, 1981, s. 2(h.11) and (h.12)). Section 24(2)(k) makes certified body-gripping traps mandatory for beaver, bobcat, otter, lynx, marten, fisher, ermine, least weasel, long-tailed weasel, muskrat and raccoon. Section 24(2)(i) separately requires a certified restraining trap for any foot-hold trap set on land for live capture and restraint of any fur animal (or, where no trap is certified for the species, a trap modified to improve humaneness). AIHTS was agreed in 1997 and ratified by Canada in June 1999; it covers 12 North American species. Phase 1 regulated species in Saskatchewan are coyote, wolf, lynx, bobcat, beaver, otter, muskrat, marten, fisher, raccoon, badger and short-tailed weasel (ermine). Phase 2 species are not yet regulated.","phase_2_restraining_not_yet_mandatory":[{"models_approx":21,"note":"","species":"Coyote"},{"models_approx":20,"note":"Cage and box traps.","species":"Raccoon"}],"provincial_regulation_url":"https://publications.saskatchewan.ca/api/v1/products/1602/formats/2841/download","source_updated":"2026-07-22","source_url":"https://fur.ca/wp-content/uploads/2026/07/CertifiedTrapsList_FIC_July-22-2026-_EN.pdf","trap_rules":["Body-gripping traps must be certified traps for beaver, bobcat, otter, lynx, marten, fisher, ermine, least weasel, long-tailed weasel, muskrat and raccoon (s. 24(2)(k)).","A foot-hold trap used on land for live capture and restraint must be a certified restraining trap, or, where no trap is certified for the species, a trap modified to improve humaneness (s. 24(2)(i)).","Traps with an inside jaw spread exceeding 24 cm are prohibited (s. 24(2)(d)); no serrated teeth or jaws (s. 24(2)(e)); no hooks or sharp devices to snag or spear fur animals (s. 24(2)(f)).","Foot-hold traps set in water for beaver, otter, mink or muskrat must be set so the animal drowns when caught (s. 24(2)(c)).","Every snare must be equipped with a locking device to prevent the noose from opening (s. 24(2)(h)).","No trap or snare may be left set for a fur animal after the close of that animal's open season (s. 24(2)(b)).","Trap check: at least every 24 hours if set in the southern fur conservation area in a town or city with a population over 1,000 people or within 5 km of one, and for mechanically activated foot snares set for black bear in the southern fur conservation area; at least every 72 hours elsewhere in the southern fur conservation area; at least every 120 hours in the northern fur conservation area (s. 24(3)).","Black bear may only be taken with mechanically activated foot snares (s. 24(1.1)).","Free-hanging neck snares require a Special Permit from the ministry; they may not be used in the southern fur conservation area except for livestock predation control; permit snares must come from a ministry-approved supplier and be tagged with the trapper's HAL number or name and phone number (ministry Fur Program summary).","Power snares and power-assisted snares require a licence issued by the director under s. 6(2) (s. 24(2)(j)).","Spring-pole sets on poles or trees must be set to kill the animal with reasonable dispatch (s. 24(2)(g)).","No person shall touch or interfere with any legally placed trap or snare unless authorized by the owner (s. 24(2)(a))."]},"license_summary":{"certified_traps":"Saskatchewan adopts the Fur Institute of Canada certified-trap lists by reference: 'certified trap' and 'certified restraining trap' are defined as traps on the FIC lists certified under AIHTS (The Wildlife Regulations, 1981, s. 2(h.11) and (h.12)). See the 'aihts' section of this dataset.","course":"First-time trappers must satisfy s. 33(1)(a): be a Saskatchewan resident, hold a firearm safety/hunter education certificate, and either obtain a mark set by the minister on a minister-approved trapping examination, have previously held a lawful trapping licence in Saskatchewan or elsewhere, or have completed a minister-approved trapping course. In practice: a recognized humane trapper education course or an equivalency test at a Ministry of Environment office (pass mark 75%). Courses are delivered by the Saskatchewan Trappers Association in the south and the Northern Saskatchewan Trappers Association in the north. Persons born after January 1, 1971 must graduate from a firearm safety/hunter education course to hold a fur licence. Youth aged 12 to 15 must be accompanied by a parent or guardian when using a firearm while trapping; youth under 16 may not use a firearm while trapping.","fees":"Southern Fur Conservation Area Fur Licence $45; Northern Fur Conservation Area Fur Licence $25; Saskatchewan Resident Youth Fur Licence no fee; Saskatchewan Treaty Indian Fur Licence no fee (The Wildlife Regulations, 1981, Table 3, includes GST; confirmed on saskatchewan.ca). Saskatchewan Wildlife Habitat Licence $20 including GST (s. 37.1); Veteran Wildlife Habitat Licence $0 (s. 37.11). Resident Fur Dealer Licence $65 plus an agent fee (maximum 3 agents); Non-resident Fur Dealer Licence $480 (Table 3).","fur_conservation_areas":"The province is split into two fur conservation areas (The Wildlife Regulations, 1981, s. 55): the Northern Fur Conservation Area (NFCA) - non-leased provincial land north of the Highway 3 / Highway 35 / Highway 49 line to the Manitoba border, plus the North Saskatchewan River / Township 44 block and Duck Mountain Provincial Park - and the Southern Fur Conservation Area (SFCA), the rest of the province. The NFCA is divided into trapping blocks (88 in 1946, per the ministry Fur Program summary), each run by its members through a Representative Council of up to 5 members (s. 56) with a certificate of registration and map (s. 57). A trapper must be voted in by block members to trap there; a licence holder inactive for two years relinquishes block privileges (s. 58). Unallocated vacant Crown land north of the block line is treated as NFCA special areas, open without block membership (ministry Fur Program summary).","harvest_report":"There is no Ontario-style season-end harvest report filed by individual trappers. Harvest is monitored through Fur Dealer Returns of Pelts Purchased (dealers report monthly, by the 5th, under s. 41) and Fur Export Permits. The minister may require a licence holder to complete and return a hunter harvest survey as a licence condition (s. 31.4); the Annual Status of Furbearers Survey runs March 1 to April 30 each year. NFCA trappers must provide the director, on request, any information the director requires (s. 59(2)).","hunting_furbearers":"A fur licence holder may hunt fur animals other than bears or cougars with a firearm during an open fur season, provided they are not accompanying or assisting a big game hunter. Cougar may be harvested under a fur licence by trap or snare only; a firearm may only dispatch a cougar already restrained (s. 25(2)(b)). Black bear under a fur licence: in the NFCA only by a trapper conducting normal bear-trapping operations; in the SFCA only after the bear is restrained in a mechanically activated foot snare (s. 25(2)(a)). Saskatchewan residents may hunt coyotes with a firearm without a licence (s. 32(3) in the SFCA; s. 36(5)). Raccoons and skunks may be hunted without a licence outside special areas (s. 4(1)(f), (g)).","licence_types":"Southern Fur Conservation Area Fur Licence; Northern Fur Conservation Area Fur Licence (valid only in the trapping block or zone specified on the licence, s. 34); Saskatchewan Resident Youth Fur Licence (free; ages 12 to 19, s. 37.2; same rights as an SFCA or NFCA licence); Saskatchewan Treaty Indian Fur Licence (free; valid only for sale of furs taken on an Indian Reserve). SFCA licences may be bought through HAL (www.saskatchewanhal.ca) or at Ministry offices; NFCA and youth licences only at Ministry of Environment field offices.","licence_validity":"Fur licences go on sale April 1 through HAL and at Ministry offices. A fur licence plus a Wildlife Habitat Licence is valid for trapping and possessing unprocessed fur until August 31 following the date of issue (s. 31(11)).","pelt_sale_export":"A fur licence (or fur dealer licence, special permit, or Treaty Indian Fur Licence) is required to sell unprocessed pelts or parts of fur animals (s. 32(1.1)). A Fur Export Permit is required before shipping or moving raw fur pelts out of Saskatchewan to another province or country (The Wildlife Act, 1998, s. 31(1)). A CITES permit is additionally required to ship pelts or parts of black bear, bobcat, lynx, otter and wolf across international borders. Shipments of wildlife must be tagged or marked with the owner's name and address, the licence number under which the wildlife was taken, and the contents (s. 53).","permission":"Southern fur conservation area: trap only on land where you have permission from the landowner or occupant (or the controlling government agency for Crown land); consent rules under The Wildlife Act, 1998, s. 41 and The Wildlife Regulations, 1981, s. 6.01. Northern fur conservation area: trap only in the trapping block or zone on your licence, and only as a voted-in block member (ss. 34, 55-57). Landowners and occupants have prior trapping rights on waters bordering their land in the SFCA (s. 35). No traps or firearms within 500 metres of an occupied building, stockade or corral without the owner's consent (s. 13). Fur licences are not valid in national parks; trapping in most provincial parks requires the written authority of the park manager.","quotas":"No bag or possession limits are set in The Fur Animals Open Seasons Regulations. Harvest is controlled in the northern fur conservation area by licence-stated limits: the director may limit the number of fur animals a licensee may take in a trapping block or zone, and no holder shall take more than the number stated on his or her fur licence without the director's prior authorization (s. 59).","report_violation":"Turn in Poachers and Polluters (TIPP) line 1-800-667-7561, 24 hours, 7 days a week (saskatchewan.ca).","snares":"Nets and snares for fur animals require a licence for the purpose, except snares for rabbits or squirrels, snares under ice, and mechanically activated foot snares (s. 24(1)). Free-hanging neck snares require a Special Permit from the ministry; they may not be used in the southern fur conservation area except for livestock predation control. Power snares and power-assisted snares require a licence issued by the director under s. 6(2) (s. 24(2)(j)). All snares must have a locking device (s. 24(2)(h)).","trap_check":"Return to every trap or snare to check it: at least every 24 hours if set in the southern fur conservation area in a town or city with a population over 1,000 people or within 5 km of one, and for mechanically activated foot snares set for black bear in the southern fur conservation area; at least every 72 hours elsewhere in the southern fur conservation area; at least every 120 hours in the northern fur conservation area (s. 24(3)).","trapping_licence":"A fur licence is required to hunt any fur animal (The Wildlife Regulations, 1981, s. 32(1)), together with a Saskatchewan Wildlife Habitat Licence or a Veteran Wildlife Habitat Licence. Fur licences are available to Saskatchewan residents only (s. 31(2)(a); s. 33(1)(a)). A fur licence plus a habitat licence is valid for trapping and possessing unprocessed fur until August 31 following the date of issue (s. 31(11))."},"seasons_status":null,"seasons_note":null};
window.OPOSSUM_FOOT_CANADA_DATA["YT"] = {"check_interval":{"live_holding":"Restraining sets: every 5 days.","killing":"Killing sets: every 7 days.","note":null},"tenure":"Trapping concessions - exclusive commercial trapping areas; a person may hold only one. First concession is a 1-year probationary term (renewable up to twice), then a 5-year full term.","trap_id_requirement":"None found - no trap owner-ID marking requirement in the sources searched (follow-up pass, Nov 17); identification runs through licence/tenure and pelt seals instead. Trapper name/licence/concession numbers are required with submitted carcasses and for pelt sealing, not on traps.","royalty":"None - the 2026-27 Trapping Regulations Summary requires an export permit for pelts leaving Yukon but charges no royalty (Yukon royalties abolished 1978, per a secondary source). [R2 Item 5]","nuisance_route":"None found - only defence-of-life/property self-help (Wildlife Act ss. 86-88; defence kills of big game, lynx, fox, wolverine or specially protected wildlife must be reported to a Conservation Officer ASAP). No permit, licence or program authorizing paid problem-wildlife trapping was found. [R2 Item 3]","harvest_reporting_and_sealing":"All lynx, wolf and wolverine pelts must have a metal seal secured by a conservation officer/designate by the earlier of 15 days after season close or before sale/transfer. Trappers in named areas are contacted to submit lynx carcasses; all trappers are invited to submit whole wolverine carcasses. [R1 s.5]","aihts_canada_only":{"canada_wide":"AIHTS in force in Canada since 1 June 1999 (Canada, the EU and Russia are parties; the US is not a party). FIC-certified traps mandatory per Phase 1 lists - killing traps: beaver, Canada lynx & bobcat, fisher, marten, muskrat (on land and underwater), otter, raccoon, weasels/ermine; restraining traps: beaver (cage), bobcat, Canada lynx, raccoon, wolf. Conventional steel-jawed leghold restraining traps on land are effectively banned for AIHTS species. Killing neck snares are NOT AIHTS traps and are not FIC-certified; provinces regulate snares separately. [R1 s.2a]","jurisdiction_specific":"Yukon summary states expressly that identical pre-certification trap models generally remain usable if unmodified. [R1 s.2a]"},"aihts":{"certified_killing_traps_schedule_1":[{"models_approx":25,"note":"Certified killing traps required (Trapping Regulations s. 4(1)(e)). List as printed in the 2026-2027 Summary, p. 13.","species":"Beaver"},{"models_approx":19,"note":"Certified killing traps required (s. 4(1)(e)). Summary, p. 14.","species":"Canada lynx"},{"models_approx":14,"note":"Certified killing traps required (s. 4(1)(e)). Summary, p. 14.","species":"Fisher"},{"models_approx":16,"note":"Certified killing traps required (s. 4(1)(e)). Summary, p. 15.","species":"Marten"},{"models_approx":37,"note":"Certified killing traps required on land (s. 4(1)(e)). Underwater, any jaw-type trap set as a submersion set is permitted. Summary, pp. 15-16.","species":"Muskrat (on land)"},{"models_approx":16,"note":"Certified killing traps required (s. 4(1)(e)). Summary, p. 17.","species":"River otter"},{"models_approx":26,"note":"Certified killing traps required for ermine and least weasel (s. 4(1)(e)); the Summary's list is headed 'Weasel/Ermine'. Summary, pp. 17-18.","species":"Weasel/ermine"}],"certified_restraining_traps_schedule_2":[{"models_approx":6,"note":"Cage traps only. Summary, p. 18.","species":"Beaver (cage traps)"},{"models_approx":5,"note":"Certified restraining traps required (s. 4(1)(f)): foot snares and specified soft-catch leghold configurations. Summary, p. 18.","species":"Canada lynx"},{"models_approx":14,"note":"Certified restraining traps required (s. 4(1)(f)). Summary, p. 19.","species":"Wolf"}],"models_note":"Yukon has no trap schedules of its own: the Trapping Regulations impose certified-trap requirements by reference to the AIHTS, and the 2026-2027 Trapping Regulations Summary (pp. 13-19) reproduces the Fur Institute of Canada certified trap list of July 22, 2026. Model counts above were counted from the lists printed in the Summary; the full model-by-model lists were not transcribed in this pass. Certification does not mean a model is still manufactured - check the current FIC list at fur.ca before relying on any model.","models_transcribed":false,"no_certified_trap_required":["American mink","Arctic fox","Coyote","Red fox","Red squirrel","Wolverine"],"note":"Yukon implements the Agreement on International Humane Trapping Standards (AIHTS, 1997) directly in the Trapping Regulations: s. 4(1)(e) requires AIHTS-certified killing traps for beaver, fisher, marten, lynx, ermine, least weasel, otter and muskrat, and s. 4(1)(f) requires AIHTS-certified restraining traps for beaver, lynx and wolf. The Fur Institute of Canada administers trap testing and certification in Canada. yukon.ca lists 9 Yukon species under the AIHTS (beaver, coyote, ermine/weasel, fisher, lynx, marten, muskrat, otter, wolf), but the Regulations impose no certified-trap requirement for coyote - see verification.known_gaps.","regulation_url":"https://laws.yukon.ca/cms/images/LEGISLATION/SUBORDINATE/1982/1982-0283/1982-0283_2.pdf","source_updated":"2026-07-22","source_url":"https://fur.ca/wp-content/uploads/2026/07/CertifiedTrapsList_FIC_July-22-2026-_EN.pdf","trap_rules":["Only the devices listed in Trapping Regulations s. 4(1) may be used: (a) a leghold trap with a jaw spread less than 250 mm used solely to capture and drown muskrat, beaver, mink or otter; (b) a snare equipped with a locking device; (c) a modified leghold trap with a jaw spread less than 250 mm used solely to capture fox or coyote; (d) a mechanically powered, trigger-activated quick-kill trap that is not a leghold trap; (e) for beaver, fisher, marten, lynx, ermine, least weasel, otter or muskrat, a killing trap certified under the AIHTS; (f) for beaver, lynx or wolf, a restraining trap certified under the AIHTS.","Extended wolf season, March 11-31: only a neck snare equipped with a locking device is a permissible device for wolves (s. 4(1)(b.1)).","Non-locking snares may be used only for red squirrel (s. 4(4)). Neck snares for all other furbearing animals must have a locking device; power-assisted neck and foot snares are permitted devices (2026-2027 Summary, pp. 11-12, 20).","Prohibited devices: traps with teeth or metal serrated edges; hooks; spring poles equipped with leghold traps (s. 4(5)); dead fall traps (they do not meet the legal definition of a quick-kill trap); leghold traps with a jaw spread of more than 25 cm; certified traps whose springs or jaws have been modified in any way (Summary, p. 12).","Trap checks (s. 5): a set designed to restrain an animal must be visually inspected, and any captured animal removed, at intervals of not more than 5 days; a quick-killing set at intervals of not more than 7 days. A restraining trap in a drowning set for muskrat, beaver, mink or otter is classified as a killing set. Every trap or snare must be removed or sprung on or before the last day of the open season for the target species (s. 5(1)).","An identical trap (same make and model) manufactured before certification is still considered a certified trap and is legal to use, provided the trap has not been modified (Summary, p. 11). Trappers receive three years' notice of new certified-trap requirements.","It is an offence to set traps within one kilometre of a residence without permission (Summary, pp. 21, 25), and to trap anywhere except inside the concession area for which the trapper's licence was issued.","No person shall hunt a furbearing animal with a shotgun (s. 4(2)). A rimfire rifle may be used to kill any furbearing animal held in a legally set trap or snare (s. 8.2(3); Summary, p. 26)."]},"license_summary":{"certified_traps":"AIHTS-certified traps are required by law for the scheduled species: certified killing traps for beaver, fisher, marten, lynx, ermine, least weasel, otter and muskrat, and certified restraining traps for beaver, lynx and wolf (Trapping Regulations s. 4(1)(e)-(f)). The 2026-2027 Summary (pp. 13-19) reproduces the Fur Institute of Canada certified trap list of July 22, 2026.","concessions":"Commercial trapping requires a Registered Trapping Concession (RTC) - the exclusive right to commercially trap furbearing animals in a defined area - or membership in a Group Trapping Area. Yukon has 360 RTCs and 13 group trapping concessions (yukon.ca RTC map data). A person may hold only one concession at a time (s. 6(3)). A first concession is probationary (1 year, expiring March 31, renewable up to twice), then full-term (5 years, expiring March 31). Concessions lying mostly inside the traditional territory of a First Nation with a Final Agreement are Category 1 (the First Nation has final authority over allocation) or Category 2 (the Government of Yukon has final authority). Renewable Resources Councils recommend on assignment of vacant or underutilized concessions. Concession boundaries are legally defined by the 1:250,000 ENV.RTC map series. Trapping is also subject to First Nation laws and RRC bylaws on Settlement Land.","course":"Recognized trapper training is required to hold a trapping concession, a trapping licence, an assistant trapper licence, or group trapping area membership (Trapping Regulations ss. 6(1)(c), 8(2)). The Government of Yukon offers the Basic Trapper Training Workshop in several communities between September and June (rotating through rural communities on a three-year cycle); each participant receives the Yukon Trapper's Manual. Graduation from recognized trapper training in another province or territory may also qualify. Trappers 65 or older who previously held a Yukon trapping or assistant trapper licence are exempt.","export":"A wildlife export permit from a Department of Environment office is required to export any furbearing animal pelt or parts out of the Yukon. To export the pelt, part or product of a wolf, otter, lynx, black bear or grizzly bear out of Canada, a CITES permit is also required (issued free at Department of Environment offices, 48 hours' advance notice). Pelts of beaver, coyote, marten, lynx, otter, muskrat, weasel/ermine, wolf or fisher taken into a European Union country also need a Certificate of Origin.","fees":"Trapping licence $10.00; assistant trapper licence $10.00; senior citizens (65+) free; members of a group trapping area free (Trapping Regulations, Schedule B). Concession fees: probationary (one-year) concession or renewal $10.00; full-term (five-year) concession or renewal $20.00; group area concession or renewal $100.00. Guided trapping permit $10.00. Fur trader's licence: Yukon resident $25.00, non-resident $300.00, non-resident restricted (7 days, one per licensing year) $25.00, agent $5.00. Manufactured products licence $2.00. Schedule B also sets a $2.00 replacement licence or concession fee, while the 2026-2027 Summary (p. 6) lists a reprinted copy as free - see verification.known_gaps.","first_nations":"Members of Yukon First Nations with Final Agreements have rights to trap furbearers for food in their traditional territory under their land claims agreements, without a commercial licence; the same applies to trapping for food in asserted traditional territory where claims are unsettled. Commercial trapping (selling pelts or by-products) is a commercial activity subject to the Wildlife Act and Regulations and requires a trapping or assistant trapper licence (Final Agreements ss. 16.4.5 and 16.4.11; Gwich'in Comprehensive Land Claim Agreement, Appendix C, s. 12.3.10). About 70 percent or more of traplines are to be held by citizens of First Nations with Final Agreements.","harvest_report":"There is no Ontario-style season-end harvest report for trappers. The Government of Yukon monitors the annual fur harvest through trapping licences, export permits, fur dealer and taxidermist records, and pelt seals (2026-2027 Summary, p. 39). Harvest documentation matters: it feeds trapping concession utilization reviews at renewal. Fur traders must submit Record of Wildlife Purchased or Received forms to a conservation officer within 10 days after the end of each month (s. 14(3)). At sealing, and with any voluntarily submitted carcass, the trapper must provide: trapper name, trapping licence number, concession number, harvest date, method of harvest, and sex of the animal.","hunting_furbearers":"A trapping licence is also a hunting authorization for furbearers: the holder of a trapping or assistant trapper licence may hunt and trap furbearing animals in the places and during the times prescribed in Schedule A (s. 3(1)), and may hunt furbearers inside their own concession area during the open season (s. 8.2(2)) - rimfire, or centrefire under 6 mm bore, for species other than wolf, wolverine and coyote; centrefire rifle for wolf, wolverine and coyote. Wolf, coyote and wolverine are also big game animals and may be hunted under a big game hunting licence under the hunting regime (seasons and bag limits in the Yukon Hunting Regulations Summary 2026-2027; not modelled in this dataset). Trapping concession holders can buy a Yukon resident big game hunting licence for half price ($5.00).","licence_types":"Trapping licence (concession holders only); assistant trapper licence (issued at the request of, and cancellable by, the concession holder); group trapping area membership (licence free); guided trapping permit (concession holder with a wilderness tourism licence may supervise up to two clients for up to two weeks; fur harvested belongs to the concession holder).","permission":"A trapper may harvest only in the concession area for which their trapping licence was issued. No trapping within one kilometre of a residence without permission. On Settlement Land, First Nation laws and Renewable Resources Council bylaws may also apply.","quotas":"There are no bag limits for trapping in Yukon. Species quotas exist only as conditions of individual trapping concessions: under s. 19 of the Trapping Regulations, the maximum number of a species that may be taken on a concession is set out as a condition on the concession document (the former Schedule E quota table was revoked effective July 1, 2004); where no maximum is set, there is deemed to be no quota. Exceeding a quota is prohibited, and excess animals must be delivered to a conservation officer. The documented example is marten: quotas are in place on most concessions in the Marten Conservation Area of southern Yukon, and once a concession reaches its marten quota all marten trapping on it must stop for the season.","report_violation":"Turn in Poachers and Polluters (TIPP) line 1-800-661-0525 - toll-free, 24 hours a day, anonymous, rewards available; report online at Yukon.ca/TIPP. Conservation Officer Services (Whitehorse): 867-667-8005.","sealing":"All lynx, wolf and wolverine pelts must be sealed with a metal seal by a conservation officer or designate by the earlier of: within 15 days of the close of the trapping season for that species, or prior to the sale or transfer of the pelt (Trapping Regulations s. 20). A trapper who remains on the trapline for the extended wolf snaring season (March 11-31) may get the sealing deadline extended to April 15 with the prior written approval of a conservation officer (s. 20.1).","trap_check":"Restraining sets must be checked at least once every 5 days and killing (quick-kill) sets at least once every 7 days, and any captured animal removed (Trapping Regulations s. 5(2)-(3); 2026-2027 Summary, p. 22). A restraining trap in a drowning set for muskrat, beaver, mink or otter is classified as a killing set. All traps and snares must be removed or sprung by the last day of the season for the target species (s. 5(1)).","trapping_licence":"A trapping licence is required and is available only to the holder of a valid trapping concession, for that concession area (2026-2027 Summary, p. 6). Qualifications (Trapping Regulations s. 6(1)): at least 16 years old; Canadian citizen or permanent resident whose principal residence has been in Yukon for at least 12 months (and physically present at least 185 days in that period, or qualifying under a residency exemption); eligible for a Yukon hunting licence; no previous convictions for offences under the Wildlife Act or Regulations (unless the Minister agrees otherwise); and successful completion of a Minister-approved trapper education course. Canadian citizens or permanent residents living outside Yukon but within 150 km of the concession area applied for may be deemed Yukon residents (s. 2(2)). Licences are annual: the 2026-2027 licences are valid July 1, 2026 to June 30, 2027 (s. 8.4). Licences are issued electronically through an Environment eServices account but must still be picked up at a Department of Environment office with Yukon identification."},"seasons_status":null,"seasons_note":null};
